import { createRoute, z } from '@hono/zod-openapi'

const AuthRuleTokenSchema = z
  .uuid()
  .openapi({ title: 'Auth Rule Token', description: 'Auth Rule Token' })
  .openapi('AuthRuleToken')

const AuthRuleStateSchema = z
  .enum(['ACTIVE', 'INACTIVE'])
  .openapi({ title: 'Auth Rule State', description: 'The state of the Auth Rule' })
  .openapi('AuthRuleState')

const ProgramLevelSchema = z
  .boolean()
  .openapi({
    title: 'Auth Rule Program Level Parameter',
    description:
      'Deprecated: Use `entities.include` with a `PROGRAM` entity instead.\n\nWhether the Auth Rule applies to all authorizations on the card program.',
    deprecated: true,
  })
  .openapi('ProgramLevel')

const CardTokensSchema = z
  .array(z.uuid())
  .openapi({
    title: 'Auth Rule Card Tokens',
    description:
      'Deprecated: Use `entities.include` with `CARD` entities instead.\n\nCard tokens to which the Auth Rule applies. Cards the rule applies to through a `CARD_TAG` entity are not listed.',
    deprecated: true,
  })
  .openapi('CardTokens')

const ExcludedCardTokensSchema = z
  .array(z.uuid())
  .openapi({
    title: 'Auth Rule Excluded Card Tokens',
    description:
      'Deprecated: Use `entities.exclude` with `CARD` entities instead.\n\nCard tokens to which the Auth Rule does not apply. Cards excluded through a `CARD_TAG` entity are not listed.',
    deprecated: true,
  })
  .openapi('ExcludedCardTokens')

const ExcludedAccountTokensSchema = z
  .array(z.uuid())
  .openapi({
    title: 'Auth Rule Excluded Account Tokens',
    description:
      'Deprecated: Use `entities.exclude` with `ACCOUNT` entities instead.\n\nAccount tokens to which the Auth Rule does not apply.',
    deprecated: true,
  })
  .openapi('ExcludedAccountTokens')

const ExcludedBusinessAccountTokensSchema = z
  .array(z.uuid())
  .openapi({
    title: 'Auth Rule Excluded Business Account Tokens',
    description:
      'Deprecated: Use `entities.exclude` with `BUSINESS_ACCOUNT` entities instead.\n\nBusiness account tokens to which the Auth Rule does not apply.',
    deprecated: true,
  })
  .openapi('ExcludedBusinessAccountTokens')

const AccountTokensSchema = z
  .array(z.uuid())
  .openapi({
    title: 'Auth Rule Account Tokens',
    description:
      'Deprecated: Use `entities.include` with `ACCOUNT` entities instead.\n\nAccount tokens to which the Auth Rule applies.',
    deprecated: true,
  })
  .openapi('AccountTokens')

const BusinessAccountTokensSchema = z
  .array(z.uuid())
  .openapi({
    title: 'Auth Rule Business Account Tokens',
    description:
      'Deprecated: Use `entities.include` with `BUSINESS_ACCOUNT` entities instead.\n\nBusiness Account tokens to which the Auth Rule applies.',
    deprecated: true,
  })
  .openapi('BusinessAccountTokens')

const AuthRuleProgramEntitySchema = z
  .object({ type: z.literal('PROGRAM') })
  .openapi({
    title: 'Program Entity',
    description: 'The entire card program. Takes no other fields.',
    required: ['type'],
  })
  .openapi('AuthRuleProgramEntity')

const AuthRuleCardEntitySchema = z
  .object({
    type: z.literal('CARD'),
    token: z.uuid().openapi({ description: 'Token of the card' }),
  })
  .openapi({ title: 'Card Entity', description: 'A single card.', required: ['type', 'token'] })
  .openapi('AuthRuleCardEntity')

const AuthRuleAccountEntitySchema = z
  .object({
    type: z.literal('ACCOUNT'),
    token: z.uuid().openapi({ description: 'Token of the account' }),
  })
  .openapi({
    title: 'Account Entity',
    description: 'A single account.',
    required: ['type', 'token'],
  })
  .openapi('AuthRuleAccountEntity')

const AuthRuleBusinessAccountEntitySchema = z
  .object({
    type: z.literal('BUSINESS_ACCOUNT'),
    token: z.uuid().openapi({ description: 'Token of the business account' }),
  })
  .openapi({
    title: 'Business Account Entity',
    description: 'A single business account.',
    required: ['type', 'token'],
  })
  .openapi('AuthRuleBusinessAccountEntity')

const AuthRuleCardTagEntitySchema = z
  .object({
    type: z.literal('CARD_TAG'),
    key: z
      .string()
      .min(1)
      .max(40)
      .openapi({
        description:
          'Tag key. Keys starting with `lithic.` (case-insensitive) are reserved and rejected.',
      }),
    value: z.string().min(1).max(500).openapi({ description: 'Tag value' }),
  })
  .openapi({
    title: 'Card Tag Entity',
    description: 'Every card whose `tags` contain `key` set to `value`.',
    required: ['type', 'key', 'value'],
  })
  .openapi('AuthRuleCardTagEntity')

const AuthRuleEntitySchema = z
  .discriminatedUnion('type', [
    AuthRuleProgramEntitySchema,
    AuthRuleCardEntitySchema,
    AuthRuleAccountEntitySchema,
    AuthRuleBusinessAccountEntitySchema,
    AuthRuleCardTagEntitySchema,
  ])
  .openapi({
    title: 'Auth Rule Entity',
    description:
      'An entity that an Auth Rule can apply to. The `type` field determines which other fields are present.\n\n- `PROGRAM`: the entire card program.\n- `CARD`: a single card.\n- `ACCOUNT`: a single account.\n- `BUSINESS_ACCOUNT`: a single business account.\n- `CARD_TAG`: every card that carries the given tag (`key` and `value`).\n\n`CARD` and `CARD_TAG` entities can only be used with rules on the `AUTHORIZATION`, `THREE_DS_AUTHENTICATION`, `TOKENIZATION` and `CARD_TRANSACTION_UPDATE` event streams. Rules on the other event streams accept `PROGRAM`, `ACCOUNT` and `BUSINESS_ACCOUNT` only.\n',
    discriminator: {
      propertyName: 'type',
      mapping: {
        PROGRAM: '#/components/schemas/auth-rule-program-entity',
        CARD: '#/components/schemas/auth-rule-card-entity',
        ACCOUNT: '#/components/schemas/auth-rule-account-entity',
        BUSINESS_ACCOUNT: '#/components/schemas/auth-rule-business-account-entity',
        CARD_TAG: '#/components/schemas/auth-rule-card-tag-entity',
      },
    },
  })
  .openapi('AuthRuleEntity')

const AuthRuleEntitiesResponseSchema = z
  .object({
    include: z
      .array(AuthRuleEntitySchema)
      .openapi({ description: 'Entities the Auth Rule applies to' }),
    exclude: z
      .array(AuthRuleEntitySchema)
      .openapi({ description: 'Entities the Auth Rule does not apply to' }),
  })
  .openapi({
    title: 'Auth Rule Entities Response',
    description:
      'The entities the Auth Rule applies to (`include`) and does not apply to (`exclude`). An exclusion overrides an inclusion.\n',
    required: ['include', 'exclude'],
  })
  .openapi('AuthRuleEntitiesResponse')

const AuthRuleTypeSchema = z
  .enum(['VELOCITY_LIMIT', 'MERCHANT_LOCK', 'CONDITIONAL_ACTION', 'TYPESCRIPT_CODE', 'OTHER'])
  .openapi({
    title: 'Auth Rule Types',
    description:
      'The type of Auth Rule. For certain rule types, this determines the event stream during which it will be evaluated. For rules that can be applied to one of several event streams, the effective one is defined by the separate `event_stream` field.\n\n- `VELOCITY_LIMIT`: AUTHORIZATION event stream.\n- `MERCHANT_LOCK`: AUTHORIZATION event stream.\n- `CONDITIONAL_ACTION`: AUTHORIZATION, THREE_DS_AUTHENTICATION, TOKENIZATION, ACH_CREDIT_RECEIPT, ACH_DEBIT_RECEIPT, CARD_TRANSACTION_UPDATE, or ACH_PAYMENT_UPDATE event stream.\n- `TYPESCRIPT_CODE`: AUTHORIZATION, THREE_DS_AUTHENTICATION, TOKENIZATION, ACH_CREDIT_RECEIPT, ACH_DEBIT_RECEIPT, CARD_TRANSACTION_UPDATE, or ACH_PAYMENT_UPDATE event stream.\n- `OTHER`: A rule whose type is not exposed through this API. Rules of this type are read-only; `OTHER` cannot be used when creating a rule.',
  })
  .openapi('AuthRuleType')

const VelocityScopeSchema = z
  .enum(['CARD', 'ACCOUNT'])
  .openapi({
    title: 'Velocity Limits Scope',
    description: 'The scope the velocity is calculated for',
  })
  .openapi('VelocityScope')

const VelocityLimitPeriodSchema = z
  .xor([
    z
      .object({
        duration: z
          .int()
          .min(10)
          .max(7776000)
          .openapi({
            description:
              'The size of the trailing window to calculate Spend Velocity over in seconds. The minimum value is 10 seconds, and the maximum value is 7776000 seconds (90 days).',
          }),
        type: z.literal('CUSTOM'),
      })
      .openapi({ title: 'Trailing Window Object', required: ['duration', 'type'] }),
    z
      .object({ type: z.literal('DAY') })
      .openapi({
        title: 'Fixed Window Day',
        description: 'Velocity over the current day since 00:00 / 12 AM in Eastern Time',
        required: ['type'],
      }),
    z
      .object({
        type: z.literal('WEEK'),
        day_of_week: z
          .int()
          .min(1)
          .max(7)
          .default(1)
          .exactOptional()
          .openapi({
            description:
              'The day of the week to start the week from. Following ISO-8601, 1 is Monday and 7 is Sunday. Defaults to Monday if not specified.',
          }),
      })
      .openapi({
        title: 'Fixed Window Week',
        description:
          'Velocity over the current week since 00:00 / 12 AM in Eastern Time on specified `day_of_week`',
        required: ['type'],
      }),
    z
      .object({
        type: z.literal('MONTH'),
        day_of_month: z
          .int()
          .min(1)
          .max(31)
          .default(1)
          .exactOptional()
          .openapi({
            description:
              'The day of the month to start from. Accepts values from 1 to 31, and will reset at the end of the month if the day exceeds the number of days in the month. Defaults to the 1st of the month if not specified.',
          }),
      })
      .openapi({
        title: 'Fixed Window Month',
        description:
          'Velocity over the current month since 00:00 / 12 AM in Eastern Time on specified `day_of_month`.',
        required: ['type'],
      }),
    z
      .object({
        type: z.literal('YEAR'),
        day_of_month: z
          .int()
          .min(1)
          .max(31)
          .default(1)
          .exactOptional()
          .openapi({
            description:
              'The day of the month to start from. Defaults to the 1st of the month if not specified.',
          }),
        month: z
          .int()
          .min(1)
          .max(12)
          .default(1)
          .exactOptional()
          .openapi({
            description:
              'The month to start from. 1 is January and 12 is December. Defaults to January if not specified.',
          }),
      })
      .openapi({
        title: 'Fixed Window Year',
        description:
          'Velocity over the current year since 00:00 / 12 AM in Eastern Time on specified `month` and `day_of_month`. This validates the month and day of the year to start from is a real date. In the event that February 29th is selected, in non-leap years, the window will start from February 28th.',
        required: ['type'],
      }),
  ])
  .openapi({ title: 'Velocity Limit Period' })
  .openapi('VelocityLimitPeriod')

const VelocityLimitFiltersSchema = z
  .object({
    include_mccs: z
      .array(
        z
          .string()
          .regex(/^[0-9]{4}$/)
          .openapi({ example: '5542' }),
      )
      .min(1)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Merchant Category Codes to include in the velocity calculation. Transactions not matching this MCC will not be included in the calculated velocity.',
      }),
    exclude_mccs: z
      .array(
        z
          .string()
          .regex(/^[0-9]{4}$/)
          .openapi({ example: '5542' }),
      )
      .min(1)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Merchant Category Codes to exclude from the velocity calculation. Transactions matching this MCC will be excluded from the calculated velocity.',
      }),
    include_countries: z
      .array(
        z
          .string()
          .regex(/^[A-Z]{3}$/)
          .openapi({ example: 'USA' }),
      )
      .min(1)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'ISO-3166-1 alpha-3 Country Codes to include in the velocity calculation. Transactions not matching any of the provided will not be included in the calculated velocity.',
      }),
    exclude_countries: z
      .array(
        z
          .string()
          .regex(/^[A-Z]{3}$/)
          .openapi({ example: 'USA' }),
      )
      .min(1)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'ISO-3166-1 alpha-3 Country Codes to exclude from the velocity calculation. Transactions matching any of the provided will be excluded from the calculated velocity.',
      }),
    include_pan_entry_modes: z
      .array(
        z.enum([
          'AUTO_ENTRY',
          'BAR_CODE',
          'CONTACTLESS',
          'CREDENTIAL_ON_FILE',
          'ECOMMERCE',
          'ERROR_KEYED',
          'ERROR_MAGNETIC_STRIPE',
          'ICC',
          'KEY_ENTERED',
          'MAGNETIC_STRIPE',
          'MANUAL',
          'OCR',
          'SECURE_CARDLESS',
          'UNSPECIFIED',
          'UNKNOWN',
        ]),
      )
      .min(1)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'PAN entry modes to include in the velocity calculation. Transactions not matching any of the provided will not be included in the calculated velocity.',
      }),
  })
  .openapi({ title: 'Velocity Limits Filters', required: [] })
  .openapi('VelocityLimitFilters')

const VelocityLimitParametersSchema = z
  .object({
    scope: VelocityScopeSchema,
    period: VelocityLimitPeriodSchema,
    filters: VelocityLimitFiltersSchema.exactOptional(),
    limit_amount: z
      .union([
        z
          .null()
          .nullable()
          .openapi({
            title: 'Null (no amount limit)',
            description: 'No velocity limit on amount is applied to the transaction.',
          }),
        z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64().min(0n),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            minimum: 0,
            title: 'Limit',
            description:
              'The maximum amount of spend velocity allowed in the period in minor units (the smallest unit of a currency, e.g. cents for USD). Transactions exceeding this limit will be declined.',
            example: 10000,
          }),
      ])
      .exactOptional(),
    limit_count: z
      .union([
        z
          .null()
          .nullable()
          .openapi({
            title: 'Null (no limit)',
            description: 'No limit on the number of velocity impacting events is applied.',
          }),
        z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64().min(0n),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            minimum: 0,
            title: 'Limit',
            description:
              'The number of spend velocity impacting transactions may not exceed this limit in the period. Transactions exceeding this limit will be declined.\nA spend velocity impacting transaction is a transaction that has been authorized, and optionally settled, or a force post (a transaction that settled without prior authorization).',
          }),
      ])
      .exactOptional(),
    limit_cash_amount: z
      .union([
        z
          .null()
          .nullable()
          .openapi({
            title: 'Null (no cash amount limit)',
            description: 'No velocity limit on cash amount is applied to the transaction.',
          }),
        z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64().min(0n),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            minimum: 0,
            title: 'Limit',
            description:
              'The maximum amount of cash spend velocity allowed in the period in minor units (the smallest unit of a currency, e.g. cents for USD). Cash spend covers ATM withdrawals, cash disbursements, and purchases with cashback. Transactions exceeding this limit will be declined.',
            example: 5000,
          }),
      ])
      .exactOptional(),
    limit_cash_count: z
      .union([
        z
          .null()
          .nullable()
          .openapi({
            title: 'Null (no cash count limit)',
            description: 'No limit on the number of cash velocity impacting events is applied.',
          }),
        z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64().min(0n),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            minimum: 0,
            title: 'Limit',
            description:
              'The number of cash spend velocity impacting transactions may not exceed this limit in the period. Transactions exceeding this limit will be declined.\nA cash velocity impacting transaction is an ATM withdrawal, cash disbursement, or purchase with cashback that has been authorized, and optionally settled, or a force post (a transaction that settled without prior authorization).',
          }),
      ])
      .exactOptional(),
  })
  .openapi({ title: 'Velocity Limit Parameters', required: ['scope', 'period'] })
  .openapi('VelocityLimitParameters')

const MerchantLockParametersSchema = z
  .object({
    merchants: z
      .array(
        z
          .union([
            z
              .unknown()
              .superRefine((val, ctx) => {
                if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                  if (!Object.hasOwn(val, 'merchant_id')) {
                    ctx.addIssue({ code: 'custom' })
                  }
                }
              })
              .openapi({ required: ['merchant_id'] }),
            z
              .unknown()
              .superRefine((val, ctx) => {
                if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                  if (!Object.hasOwn(val, 'descriptor')) {
                    ctx.addIssue({ code: 'custom' })
                  }
                }
              })
              .openapi({ required: ['descriptor'] }),
          ])
          .and(
            z
              .object({
                merchant_id: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'Unique alphanumeric identifier for the payment card acceptor (merchant). This attribute specifies the merchant entity that will be locked or referenced for authorization rules.',
                  }),
                descriptor: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'Short description of the merchant, often used to provide more human-readable context about the transaction merchant. This is typically the name or label shown on transaction summaries.',
                  }),
                comment: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'A comment or explanation about the merchant, used internally for rule management purposes.',
                  }),
              })
              .openapi({ required: [] }),
          )
          .openapi({
            description:
              'Represents a specific merchant lock based on their ID or descriptor. Each merchant object allows transaction rules to work at a granular level and requires at least one of merchant_id or descriptor.',
          }),
      )
      .openapi({
        description:
          'A list of merchant locks defining specific merchants or groups of merchants (based on descriptors or IDs) that the lock applies to.',
      }),
    locked_at: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ readOnly: true, description: 'Timestamp of when the merchant lock was created' }),
  })
  .openapi({ title: 'Merchant Lock Inputs', required: ['merchants'] })
  .openapi('MerchantLockParameters')

const Authentication_3dsActionSchema = z
  .enum(['DECLINE', 'CHALLENGE'])
  .openapi({ title: 'Authentication (3DS) Action' })
  .openapi('Authentication_3dsAction')

const ConditionalOperationSchema = z
  .enum([
    'IS_ONE_OF',
    'IS_NOT_ONE_OF',
    'MATCHES',
    'DOES_NOT_MATCH',
    'IS_EQUAL_TO',
    'IS_NOT_EQUAL_TO',
    'IS_GREATER_THAN',
    'IS_GREATER_THAN_OR_EQUAL_TO',
    'IS_LESS_THAN',
    'IS_LESS_THAN_OR_EQUAL_TO',
    'IS_AFTER',
    'IS_BEFORE',
    'CONTAINS_ANY',
    'CONTAINS_ALL',
    'CONTAINS_NONE',
  ])
  .openapi({
    title: 'Conditional Operation',
    description: 'The operation to apply to the attribute',
  })
  .openapi('ConditionalOperation')

const ConditionalValueSchema = z
  .union([
    z
      .string()
      .openapi({
        title: 'Regex',
        description: 'A regex string, to be used with `MATCHES` or `DOES_NOT_MATCH`',
      }),
    z
      .union([
        z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64(),
          )
          .openapi({ type: 'integer', format: 'int64' }),
        z.number(),
      ])
      .openapi({
        title: 'Number',
        description:
          'A number, to be used with `IS_GREATER_THAN`, `IS_GREATER_THAN_OR_EQUAL_TO`, `IS_LESS_THAN`, `IS_LESS_THAN_OR_EQUAL_TO`, `IS_EQUAL_TO`, or `IS_NOT_EQUAL_TO`',
      }),
    z
      .array(z.string())
      .min(1)
      .openapi({
        title: 'List of Strings',
        description: 'An array of strings, to be used with `IS_ONE_OF` or `IS_NOT_ONE_OF`',
      }),
    z.iso
      .datetime({ offset: true })
      .openapi({
        title: 'Timestamp',
        description: 'A timestamp, to be used with `IS_AFTER` or `IS_BEFORE`',
      }),
  ])
  .openapi({ title: 'Conditional Value' })
  .openapi('ConditionalValue')

const Conditional_3dsActionParametersSchema = z
  .object({
    action: Authentication_3dsActionSchema.openapi({
      description: 'The action to take if the conditions are met.',
    }),
    conditions: z.array(
      z
        .object({
          attribute: z
            .enum([
              'MCC',
              'COUNTRY',
              'CURRENCY',
              'MERCHANT_ID',
              'DESCRIPTOR',
              'TRANSACTION_AMOUNT',
              'RISK_SCORE',
              'MESSAGE_CATEGORY',
              'ADDRESS_MATCH',
              'CARD_STATE',
              'CARD_TYPE',
              'CARD_PROGRAM_FAMILY',
              'PIN_STATUS',
              'CARD_AGE',
            ])
            .openapi({
              description:
                "The attribute to target.\n\nThe following attributes may be targeted:\n* `MCC`: A four-digit number listed in ISO 18245. An MCC is used to classify a business by the types of goods or services it provides.\n* `COUNTRY`: Country of entity of card acceptor. Possible values are: (1) all ISO 3166-1 alpha-3 country codes, (2) QZZ for Kosovo, and (3) ANT for Netherlands Antilles.\n* `CURRENCY`: 3-character alphabetic ISO 4217 code for the merchant currency of the transaction.\n* `MERCHANT_ID`: Unique alphanumeric identifier for the payment card acceptor (merchant).\n* `DESCRIPTOR`: Short description of card acceptor.\n* `TRANSACTION_AMOUNT`: The base transaction amount (in cents) plus the acquirer fee field in the settlement/cardholder billing currency. This is the amount the issuer should authorize against unless the issuer is paying the acquirer fee on behalf of the cardholder. Use an integer value.\n* `RISK_SCORE`: Mastercard, and Visa in some markets: Assessment by the network of the authentication risk level, with a higher value indicating a higher amount of risk. Use an integer value.\n* `MESSAGE_CATEGORY`: The category of the authentication being processed.\n* `ADDRESS_MATCH`: Lithic's evaluation result comparing transaction's address data with the cardholder KYC data if it exists. Valid values are `MATCH`, `MATCH_ADDRESS_ONLY`, `MATCH_ZIP_ONLY`,`MISMATCH`,`NOT_PRESENT`.\n* `CARD_STATE`: The current state of the card associated with the authentication. Valid values are `CLOSED`, `OPEN`, `PAUSED`, `PENDING_ACTIVATION`, `PENDING_FULFILLMENT`.\n* `CARD_TYPE`: The type of the card associated with the authentication. Valid values are `MERCHANT_LOCKED`, `PHYSICAL`, `SINGLE_USE`, `VIRTUAL`.\n* `CARD_PROGRAM_FAMILY`: The program family of the card associated with the authentication. Valid values are `CONSUMER`, `COMMERCIAL`.\n* `PIN_STATUS`: The current state of card's PIN. Valid values are `NOT_SET`, `OK`, `BLOCKED`.\n* `CARD_AGE`: The age of the card in seconds at the time of the authentication. Use an integer value.",
            }),
          operation: ConditionalOperationSchema,
          value: ConditionalValueSchema,
        })
        .openapi({ required: ['attribute', 'operation', 'value'] }),
    ),
  })
  .openapi({ title: 'Conditional Action (3DS) Parameters', required: ['action', 'conditions'] })
  .openapi('Conditional_3dsActionParameters')

const AuthorizationActionSchema = z
  .enum(['DECLINE', 'CHALLENGE'])
  .openapi({ title: 'Authorization Action' })
  .openapi('AuthorizationAction')

const HoldAdjustmentActionSchema = z
  .object({
    type: z.literal('HOLD_ADJUSTMENT').openapi({ description: 'The type of adjustment to apply' }),
    mode: z
      .enum(['REPLACE_WITH_AMOUNT', 'ADD_PERCENTAGE', 'ADD_AMOUNT'])
      .openapi({
        description:
          'The mode of the hold adjustment, determining how the value is interpreted:\n\n* `REPLACE_WITH_AMOUNT`: The value is the approved hold amount in cents.\n* `ADD_PERCENTAGE`: The value adjusts the hold amount by a percentage. 1000 represents a 10% increase, 0 represents no change.\n* `ADD_AMOUNT`: The value is added to the hold amount in cents.',
      }),
    value: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The value used for the hold adjustment, interpreted based on the mode',
      }),
  })
  .openapi({
    title: 'Hold Adjustment Action',
    description: 'The hold adjustment to apply if the conditions are met.',
    required: ['type', 'mode', 'value'],
  })
  .openapi('HoldAdjustmentAction')

const ConditionalAuthorizationActionParametersSchema = z
  .object({
    action: z
      .xor([AuthorizationActionSchema, HoldAdjustmentActionSchema])
      .openapi({ description: 'The action to take if the conditions are met.' }),
    conditions: z.array(
      z
        .object({
          attribute: z
            .enum([
              'MCC',
              'COUNTRY',
              'CURRENCY',
              'MERCHANT_ID',
              'DESCRIPTOR',
              'LIABILITY_SHIFT',
              'PAN_ENTRY_MODE',
              'TRANSACTION_AMOUNT',
              'CASH_AMOUNT',
              'RISK_SCORE',
              'CARD_TRANSACTION_COUNT_15M',
              'CARD_TRANSACTION_COUNT_1H',
              'CARD_TRANSACTION_COUNT_24H',
              'CARD_DECLINE_COUNT_15M',
              'CARD_DECLINE_COUNT_1H',
              'CARD_DECLINE_COUNT_24H',
              'CARD_STATE',
              'PIN_ENTERED',
              'PIN_STATUS',
              'WALLET_TYPE',
              'TRANSACTION_INITIATOR',
              'ADDRESS_MATCH',
              'SERVICE_LOCATION_STATE',
              'SERVICE_LOCATION_POSTAL_CODE',
              'CARD_AGE',
              'IS_DOMESTIC',
              'ACCOUNT_AGE',
              'AMOUNT_Z_SCORE',
              'AVG_TRANSACTION_AMOUNT',
              'STDEV_TRANSACTION_AMOUNT',
              'IS_NEW_COUNTRY',
              'IS_NEW_MCC',
              'IS_FIRST_TRANSACTION',
              'CONSECUTIVE_DECLINES',
              'TIME_SINCE_LAST_TRANSACTION',
              'DISTINCT_COUNTRY_COUNT',
              'IS_NEW_MERCHANT',
              'THREE_DS_SUCCESS_RATE',
              'TRAVEL_SPEED',
              'DISTANCE_FROM_LAST_TRANSACTION',
            ])
            .openapi({
              description:
                "The attribute to target.\n\nThe following attributes may be targeted:\n* `MCC`: A four-digit number listed in ISO 18245. An MCC is used to classify a business by the types of goods or services it provides.\n* `COUNTRY`: Country of entity of card acceptor. Possible values are: (1) all ISO 3166-1 alpha-3 country codes, (2) QZZ for Kosovo, and (3) ANT for Netherlands Antilles.\n* `CURRENCY`: 3-character alphabetic ISO 4217 code for the merchant currency of the transaction.\n* `MERCHANT_ID`: Unique alphanumeric identifier for the payment card acceptor (merchant).\n* `DESCRIPTOR`: Short description of card acceptor.\n* `LIABILITY_SHIFT`: Indicates whether chargeback liability shift to the issuer applies to the transaction. Valid values are `NONE`, `3DS_AUTHENTICATED`, or `TOKEN_AUTHENTICATED`.\n* `PAN_ENTRY_MODE`: The method by which the cardholder's primary account number (PAN) was entered. Valid values are `AUTO_ENTRY`, `BAR_CODE`, `CONTACTLESS`, `ECOMMERCE`, `ERROR_KEYED`, `ERROR_MAGNETIC_STRIPE`, `ICC`, `KEY_ENTERED`, `MAGNETIC_STRIPE`, `MANUAL`, `OCR`, `SECURE_CARDLESS`, `UNSPECIFIED`, `UNKNOWN`, `CREDENTIAL_ON_FILE`, or `ECOMMERCE`.\n* `TRANSACTION_AMOUNT`: The base transaction amount (in cents) plus the acquirer fee field in the settlement/cardholder billing currency. This is the amount the issuer should authorize against unless the issuer is paying the acquirer fee on behalf of the cardholder. Use an integer value.\n* `CASH_AMOUNT`: The cash amount of the transaction in minor units (cents). This represents the amount of cash being withdrawn or advanced. Use an integer value.\n* `RISK_SCORE`: Network-provided score assessing risk level associated with a given authorization. Scores are on a range of 0-999, with 0 representing the lowest risk and 999 representing the highest risk. For Visa transactions, where the raw score has a range of 0-99, Lithic will normalize the score by multiplying the raw score by 10x. Use an integer value.\n* `CARD_TRANSACTION_COUNT_15M`: The number of transactions on the card in the trailing 15 minutes before the authorization. Use an integer value.\n* `CARD_TRANSACTION_COUNT_1H`: The number of transactions on the card in the trailing hour up and until the authorization. Use an integer value.\n* `CARD_TRANSACTION_COUNT_24H`: The number of transactions on the card in the trailing 24 hours up and until the authorization. Use an integer value.\n* `CARD_DECLINE_COUNT_15M`: The number of declined transactions on the card in the trailing 15 minutes before the authorization. Use an integer value.\n* `CARD_DECLINE_COUNT_1H`: The number of declined transactions on the card in the trailing hour up and until the authorization. Use an integer value.\n* `CARD_DECLINE_COUNT_24H`: The number of declined transactions on the card in the trailing 24 hours up and until the authorization. Use an integer value.\n* `CARD_STATE`: The current state of the card associated with the transaction. Valid values are `CLOSED`, `OPEN`, `PAUSED`, `PENDING_ACTIVATION`, `PENDING_FULFILLMENT`.\n* `PIN_ENTERED`: Indicates whether a PIN was entered during the transaction. Valid values are `TRUE`, `FALSE`.\n* `PIN_STATUS`: The current state of card's PIN. Valid values are `NOT_SET`, `OK`, `BLOCKED`.\n* `WALLET_TYPE`: For transactions using a digital wallet token, indicates the source of the token. Valid values are `APPLE_PAY`, `GOOGLE_PAY`, `SAMSUNG_PAY`, `MASTERPASS`, `MERCHANT`, `OTHER`, `NONE`.\n* `TRANSACTION_INITIATOR`: The entity that initiated the transaction indicates the source of the token. Valid values are `CARDHOLDER`, `MERCHANT`, `UNKNOWN`.\n* `ADDRESS_MATCH`: Lithic's evaluation result comparing transaction's address data with the cardholder KYC data if it exists. Valid values are `MATCH`, `MATCH_ADDRESS_ONLY`, `MATCH_ZIP_ONLY`,`MISMATCH`,`NOT_PRESENT`.\n* `SERVICE_LOCATION_STATE`: The state/province code (ISO 3166-2) where the cardholder received the service, e.g. \"NY\". When a service location is present in the network data, the service location state is used. Otherwise, falls back to the card acceptor state.\n* `SERVICE_LOCATION_POSTAL_CODE`: The postal code where the cardholder received the service, e.g. \"10001\". When a service location is present in the network data, the service location postal code is used. Otherwise, falls back to the card acceptor postal code.\n* `CARD_AGE`: The age of the card in seconds at the time of the authorization. Use an integer value.\n* `IS_DOMESTIC`: Whether the merchant's country matches the card program's issuing country. Valid values are `TRUE`, `FALSE`. For programs with no issuing country configured, this attribute does not evaluate.\n* `ACCOUNT_AGE`: The age of the account holder's account in seconds at the time of the authorization. Use an integer value. For programs where Lithic does not manage or retain account holder data, this attribute does not evaluate.\n* `AMOUNT_Z_SCORE`: The z-score of the transaction amount relative to the entity's transaction history. Null if fewer than 30 approved transactions in the specified window. Requires `parameters.scope` and `parameters.interval`. Use a decimal value.\n* `AVG_TRANSACTION_AMOUNT`: The average approved transaction amount for the entity over the specified window, in cents. Requires `parameters.scope` and `parameters.interval`. Use a decimal value.\n* `STDEV_TRANSACTION_AMOUNT`: The standard deviation of approved transaction amounts for the entity over the specified window, in cents. Null if fewer than 30 approved transactions in the specified window. Requires `parameters.scope` and `parameters.interval`. Use a decimal value.\n* `IS_NEW_COUNTRY`: Whether the transaction's merchant country has not been seen in the entity's transaction history. Valid values are `TRUE`, `FALSE`. Requires `parameters.scope`.\n* `IS_NEW_MCC`: Whether the transaction's MCC has not been seen in the entity's transaction history. Valid values are `TRUE`, `FALSE`. Requires `parameters.scope`.\n* `IS_FIRST_TRANSACTION`: Whether this is the first transaction for the entity. Valid values are `TRUE`, `FALSE`. Requires `parameters.scope`.\n* `CONSECUTIVE_DECLINES`: The number of consecutive declined transactions for the entity over the last 30 days (rolling). Requires `parameters.scope`. Not supported for `BUSINESS_ACCOUNT` scope. Use an integer value.\n* `TIME_SINCE_LAST_TRANSACTION`: The number of days since the last approved transaction for the entity, rounded to the nearest whole day. Requires `parameters.scope`. Use an integer value.\n* `DISTINCT_COUNTRY_COUNT`: The number of distinct merchant countries seen in the entity's transaction history. Requires `parameters.scope`. Use an integer value.\n* `IS_NEW_MERCHANT`: Whether the card acceptor ID has not been seen in the card's approved transaction history (capped at the 1000 most recently seen merchants). Valid values are `TRUE`, `FALSE`. Card-scoped only; no `parameters` required.\n* `THREE_DS_SUCCESS_RATE`: The 3DS authentication success rate for the card, as a percentage from 0.0 to 100.0. Card-scoped only; no `parameters` required. Use a decimal value.\n* `TRAVEL_SPEED`: The estimated speed of travel derived from the distance between the postal code centers of the last card-present transaction and the current transaction, divided by the elapsed time. Null if there is no prior card-present transaction, if either postal code cannot be geocoded, or if elapsed time is zero. Requires `parameters.unit` set to `MPH` or `KPH`. Use a decimal value.\n* `DISTANCE_FROM_LAST_TRANSACTION`: The estimated distance between the postal code centers of the last card-present transaction and the current transaction. Null if there is no prior card-present transaction or if either postal code cannot be geocoded. Requires `parameters.unit` set to `MILES` or `KILOMETERS`. Use a decimal value.",
            }),
          parameters: z
            .object({
              scope: z
                .enum(['CARD', 'ACCOUNT', 'BUSINESS_ACCOUNT'])
                .exactOptional()
                .openapi({ description: 'The entity scope to evaluate the attribute against.' }),
              interval: z
                .enum(['LIFETIME', '7D', '30D', '90D'])
                .exactOptional()
                .openapi({
                  description:
                    'The time window for statistical attributes (`AMOUNT_Z_SCORE`, `AVG_TRANSACTION_AMOUNT`, `STDEV_TRANSACTION_AMOUNT`). Use `LIFETIME` for all-time history or a specific window (`7D`, `30D`, `90D`).',
                }),
              unit: z
                .enum(['MPH', 'KPH', 'MILES', 'KILOMETERS'])
                .exactOptional()
                .openapi({
                  description:
                    'The unit for impossible travel attributes. Required when `attribute` is `TRAVEL_SPEED` or `DISTANCE_FROM_LAST_TRANSACTION`.\n\nFor `TRAVEL_SPEED`: `MPH` (miles per hour) or `KPH` (kilometers per hour).\n\nFor `DISTANCE_FROM_LAST_TRANSACTION`: `MILES` or `KILOMETERS`.',
                }),
            })
            .exactOptional()
            .openapi({
              description:
                'Additional parameters for certain attributes. Required when `attribute` is one of\n`AMOUNT_Z_SCORE`, `AVG_TRANSACTION_AMOUNT`, `STDEV_TRANSACTION_AMOUNT`,\n`IS_NEW_COUNTRY`, `IS_NEW_MCC`, `IS_FIRST_TRANSACTION`, `CONSECUTIVE_DECLINES`,\n`TIME_SINCE_LAST_TRANSACTION`, or `DISTINCT_COUNTRY_COUNT` (require `scope`);\nor `TRAVEL_SPEED` or `DISTANCE_FROM_LAST_TRANSACTION` (require `unit`).\nNot used for other attributes.',
              required: [],
            }),
          operation: ConditionalOperationSchema,
          value: ConditionalValueSchema,
        })
        .openapi({ required: ['attribute', 'operation', 'value'] }),
    ),
  })
  .openapi({
    title: 'Conditional Action (Authorization) Parameters',
    required: ['action', 'conditions'],
  })
  .openapi('ConditionalAuthorizationActionParameters')

