const HoldTransactionSchema = BaseTransactionFieldsSchema.and(
  z
    .object({
      family: z.literal('HOLD').exactOptional().openapi({ description: 'HOLD - Hold Transaction' }),
      result: TransactionResultSchema.exactOptional(),
      status: HoldStatusSchema.exactOptional(),
      financial_account_token: z.uuid().exactOptional(),
      pending_amount: z
        .int()
        .exactOptional()
        .openapi({ description: 'Current pending amount (0 when resolved)' }),
      currency: z.string().exactOptional(),
      events: z.array(HoldEventSchema).exactOptional(),
      user_defined_id: z.string().nullable().exactOptional(),
      expiration_datetime: z.iso
        .datetime({ offset: true })
        .nullable()
        .exactOptional()
        .openapi({ description: 'When the hold will auto-expire if not resolved' }),
    })
    .openapi({ required: [] }),
)
  .openapi({
    title: 'Hold Transaction',
    description:
      'A hold transaction representing reserved funds on a financial account. Holds move funds from available to pending balance in anticipation of future payments. They can be resolved via settlement (linked to payment), manual release, or expiration.',
    required: [
      'family',
      'result',
      'status',
      'financial_account_token',
      'pending_amount',
      'currency',
      'events',
      'user_defined_id',
      'expiration_datetime',
    ],
  })
  .openapi('HoldTransaction')

const BaseTransactionResponseSchema = z
  .xor([
    FinancialTransactionSchema,
    BookTransferTransactionSchema,
    CardTransaction2Schema,
    PaymentTransactionSchema,
    ExternalPaymentResponseSchema,
    ManagementOperationTransactionSchema,
    HoldTransactionSchema,
  ])
  .openapi({
    title: 'Transaction Response',
    description:
      'Response containing multiple transaction types. The `family` field determines which transaction type is returned: INTERNAL returns FinancialTransaction, TRANSFER returns BookTransferTransaction, CARD returns CardTransaction, PAYMENT returns PaymentTransaction, EXTERNAL_PAYMENT returns ExternalPaymentResponse, MANAGEMENT_OPERATION returns ManagementOperationTransaction, and HOLD returns HoldTransaction',
    discriminator: {
      propertyName: 'family',
      mapping: {
        INTERNAL: '#/components/schemas/financial-transaction',
        TRANSFER: '#/components/schemas/book-transfer-transaction',
        CARD: '#/components/schemas/card-transaction2',
        PAYMENT: '#/components/schemas/payment-transaction',
        EXTERNAL_PAYMENT: '#/components/schemas/external_payment_response',
        MANAGEMENT_OPERATION: '#/components/schemas/management_operation_transaction',
        HOLD: '#/components/schemas/hold_transaction',
      },
    },
  })
  .openapi('BaseTransactionResponse')

