const AccountConfigurationSchema = z
  .object({
    account_holder: z
      .object({
        business_account_token: z
          .string()
          .openapi({
            description:
              'Only applicable for customers using the KYC-Exempt workflow to enroll authorized users of businesses. Account_token of the enrolled business associated with an enrolled AUTHORIZED_USER individual.',
            example: 'e87db14a-4abf-4901-adad-5d5c9f46aff2',
          }),
        email: z.string().openapi({ description: 'Email address.', example: 'jack@lithic.com' }),
        phone_number: z
          .string()
          .openapi({ description: 'Phone number of the individual.', example: '+15555555555' }),
        token: z
          .string()
          .openapi({
            description: 'Globally unique identifier for the account holder.',
            example: '95e5f1b7-cfd5-4520-aa3c-2451bab8608d',
          }),
      })
      .exactOptional()
      .openapi({ required: ['business_account_token', 'email', 'phone_number', 'token'] }),
    auth_rule_tokens: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'List of identifiers for the Auth Rule(s) that are applied on the account.\nThis field is deprecated and will no longer be populated in the `account_holder` object. The key will be removed from the schema in a future release. Use the `/auth_rules` endpoints to fetch Auth Rule information instead.',
        deprecated: true,
      }),
    cardholder_currency: z
      .string()
      .exactOptional()
      .openapi({
        description: '3-character alphabetic ISO 4217 code for the currency of the cardholder.',
        example: 'USD',
      }),
    spend_limit: z
      .object({
        daily: z
          .int()
          .min(0)
          .openapi({ description: 'Daily spend limit (in cents).', example: 10000 }),
        lifetime: z
          .int()
          .min(0)
          .openapi({
            description: 'Total spend limit over account lifetime (in cents).',
            example: 100000,
          }),
        monthly: z
          .int()
          .min(0)
          .openapi({ description: 'Monthly spend limit (in cents).', example: 40000 }),
      })
      .openapi({
        description:
          'Spend limit information for the user containing the daily, monthly, and lifetime spend limit of the account. Any charges to a card owned by this account will be declined once their transaction volume has surpassed the value in the applicable time limit (rolling). A lifetime limit of 0 indicates that the lifetime limit feature is disabled.\n',
        required: ['daily', 'lifetime', 'monthly'],
      }),
    state: z
      .enum(['ACTIVE', 'PAUSED', 'CLOSED'])
      .openapi({
        description:
          'Account state:\n  * `ACTIVE` - Account is able to transact and create new cards.\n  * `PAUSED` - Account will not be able to transact or create new cards. It can be set back\nto `ACTIVE`.\n  * `CLOSED` - Account will not be able to transact or create new cards. `CLOSED` accounts\nare unable to be transitioned to `ACTIVE` or `PAUSED` states. Accounts can be manually set to `CLOSED`, or this can be done by Lithic due to failure to pass KYB/KYC or for risk/compliance reasons. Please contact [support.lithic.com](https://support.lithic.com/) if you believe this was done by mistake.',
      }),
    substatus: z
      .enum([
        'FRAUD_IDENTIFIED',
        'SUSPICIOUS_ACTIVITY',
        'RISK_VIOLATION',
        'END_USER_REQUEST',
        'ISSUER_REQUEST',
        'NOT_ACTIVE',
        'INTERNAL_REVIEW',
        'OTHER',
      ])
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "Account state substatus values:\n* `FRAUD_IDENTIFIED` - The account has been recognized as being created or used with stolen or fabricated identity information, encompassing both true identity theft and synthetic identities.\n* `SUSPICIOUS_ACTIVITY` - The account has exhibited suspicious behavior, such as unauthorized access or fraudulent transactions, necessitating further investigation.\n* `RISK_VIOLATION` - The account has been involved in deliberate misuse by the legitimate account holder. Examples include disputing valid transactions without cause, falsely claiming non-receipt of goods, or engaging in intentional bust-out schemes to exploit account services.\n* `END_USER_REQUEST` - The account holder has voluntarily requested the closure of the account for personal reasons. This encompasses situations such as bankruptcy, other financial considerations, or the account holder's death.\n* `ISSUER_REQUEST` - The issuer has initiated the closure of the account due to business strategy, risk management, inactivity, product changes, regulatory concerns, or violations of terms and conditions.\n* `NOT_ACTIVE` - The account has not had any transactions or payment activity within a specified period. This status applies to accounts that are paused or closed due to inactivity.\n* `INTERNAL_REVIEW` - The account is temporarily paused pending further internal review. In future implementations, this status may prevent clients from activating the account via APIs until the review is completed.\n* `OTHER` - The reason for the account's current status does not fall into any of the above categories. A comment should be provided to specify the particular reason.\n",
      }),
    comment: z
      .string()
      .exactOptional()
      .openapi({ description: 'Additional context or information related to the account.' }),
    token: z
      .uuid()
      .openapi({
        description:
          'Globally unique identifier for the account. This is the same as the account_token returned by the enroll endpoint. If using this parameter, do not include pagination.\n',
        example: 'b68b7424-aa69-4cbc-a946-30d90181b621',
      }),
    verification_address: z
      .object({
        address1: z
          .string()
          .openapi({
            description: 'Valid deliverable address (no PO boxes).',
            example: '124 Old Forest Way',
          }),
        address2: z
          .string()
          .exactOptional()
          .openapi({ description: 'Unit or apartment number (if applicable).', example: 'Apt 21' }),
        city: z.string().openapi({ description: 'City name.', example: 'Seattle' }),
        country: z
          .string()
          .openapi({
            description: 'Country name. Only USA is currently supported.',
            example: 'USA',
          }),
        postal_code: z
          .string()
          .openapi({
            description:
              'Valid postal code. Only USA postal codes (ZIP codes) are currently supported, entered as a five-digit postal code or nine-digit postal code (ZIP+4) using the format 12345-1234.',
            example: '98109',
          }),
        state: z
          .string()
          .openapi({
            description:
              'Valid state code. Only USA state codes are currently supported, entered in uppercase ISO 3166-2 two-character format.',
            example: 'WA',
          }),
      })
      .exactOptional()
      .openapi({
        required: ['address1', 'city', 'country', 'postal_code', 'state'],
        deprecated: true,
      }),
    created: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({ description: 'Timestamp of when the account was created.' }),
  })
  .openapi({ required: ['spend_limit', 'state', 'token', 'created'] })
  .openapi('AccountConfiguration')

