const AuthRuleEntitiesSchema = z
  .object({
    include: z
      .array(AuthRuleEntitySchema)
      .exactOptional()
      .openapi({
        description: 'Entities the Auth Rule applies to. Defaults to an empty list in requests.',
      }),
    exclude: z
      .array(AuthRuleEntitySchema)
      .exactOptional()
      .openapi({
        description:
          'Entities the Auth Rule does not apply to. Defaults to an empty list in requests.',
      }),
  })
  .openapi({
    title: 'Auth Rule Entities',
    description:
      "The entities an Auth Rule applies to (`include`) and does not apply to (`exclude`). An exclusion overrides an inclusion, so a card excluded here is skipped even when the program, its account or one of its tags is included.\n\nThe rule's resulting entities must satisfy these constraints after any write:\n\n- `include` must contain at least one entity.\n- If `PROGRAM` is included, it must be the only included entity.\n- `PROGRAM` cannot be excluded.\n- An entity cannot appear in both `include` and `exclude`, or twice in the same list.\n- A rule can have at most 1,000 entities across `include` and `exclude`, not counting `PROGRAM`.\n- Entity types must be valid for the rule's event stream.\n- `CARD`, `ACCOUNT` and `BUSINESS_ACCOUNT` tokens must belong to your program.\n",
    required: [],
  })
  .openapi('AuthRuleEntities')

