const PatchAuthRuleEntitiesRequestSchema = z
  .object({
    add: AuthRuleEntitiesSchema.exactOptional().openapi({
      description: "Entities to add to the rule's `include` and `exclude` lists",
    }),
    remove: AuthRuleEntitiesSchema.exactOptional().openapi({
      description: "Entities to remove from the rule's `include` and `exclude` lists",
    }),
  })
  .openapi({
    title: 'Auth Rule Entities Patch Request',
    description:
      "Changes the rule's entities incrementally. `add` adds to the rule's `include` and `exclude` lists, and `remove` removes from them. Adding an entity that is already present, or removing one that is not, has no effect. A request with neither leaves entities unchanged.\n\nThe same entity cannot appear twice in one list, in both `add.include` and `remove.include`, or in both `add.exclude` and `remove.exclude`. To move an entity between `include` and `exclude`, remove it from one list and add it to the other in the same request.\n",
    required: [],
  })
  .openapi('PatchAuthRuleEntitiesRequest')

