const FundingAccountSchema = z
  .object({
    account_name: z
      .string()
      .exactOptional()
      .openapi({ description: 'Account name identifying the funding source. This may be `null`.' }),
    created: z.iso
      .datetime({ offset: true })
      .openapi({
        description:
          'An RFC 3339 string representing when this funding source was added to the Lithic account. This may be `null`. UTC time zone.',
      }),
    last_four: z
      .string()
      .length(4)
      .openapi({
        description:
          'The last 4 digits of the account (e.g. bank account, debit card) associated with this FundingAccount. This may be null.',
      }),
    nickname: z
      .string()
      .min(1)
      .max(255)
      .nullable()
      .exactOptional()
      .openapi({
        description: 'The nickname given to the `FundingAccount` or `null` if it has no nickname.',
      }),
    state: z
      .enum(['DELETED', 'ENABLED', 'PENDING'])
      .openapi({
        description:
          'State of funding source. Funding source states: * `ENABLED` - The funding account is available to use for card creation and transactions. * `PENDING` - The funding account is still being verified e.g. bank micro-deposits verification. * `DELETED` - The founding account has been deleted.',
      }),
    token: z
      .uuid()
      .openapi({ description: 'A globally unique identifier for this FundingAccount.' }),
    type: z
      .enum(['DEPOSITORY_CHECKING', 'DEPOSITORY_SAVINGS'])
      .openapi({
        description:
          'Types of funding source: * `DEPOSITORY_CHECKING` - Bank checking account. * `DEPOSITORY_SAVINGS` - Bank savings account.',
      }),
  })
  .openapi({
    description: 'Funding account for a card',
    required: ['created', 'last_four', 'state', 'token', 'type'],
  })
  .openapi('FundingAccount')

const SpendLimitDurationSchema = z
  .enum(['ANNUALLY', 'FOREVER', 'MONTHLY', 'TRANSACTION'])
  .openapi({
    description:
      'Spend limit duration values:\n\n* `ANNUALLY` - Card will authorize transactions up to spend limit for the trailing year.\n* `FOREVER` - Card will authorize only up to spend limit for the entire lifetime of the card.\n* `MONTHLY` - Card will authorize transactions up to spend limit for the trailing month. To support recurring monthly payments, which can occur on different day every month, the time window we consider for monthly velocity starts 6 days after the current calendar date one month prior.\n* `TRANSACTION` - Card will authorize multiple transactions if each individual transaction is under the spend limit.',
  })
  .openapi('SpendLimitDuration')

const NonPciCardResponseSchema = z
  .object({
    account_token: z
      .string()
      .openapi({
        description: 'Globally unique identifier for the account to which the card belongs.',
        example: 'f3f4918c-dee9-464d-a819-4aa42901d624',
      }),
    auth_rule_tokens: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'List of identifiers for the Auth Rule(s) that are applied on the card. This field is deprecated and will no longer be populated in the `Card` object. The key will be removed from the schema in a future release. Use the `/auth_rules` endpoints to fetch Auth Rule information instead.',
        deprecated: true,
      }),
    card_program_token: z
      .string()
      .openapi({
        description: 'Globally unique identifier for the card program on which the card exists.',
        example: '5e9483eb-8103-4e16-9794-2106111b2eca',
      }),
    bulk_order_token: z
      .uuid()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Globally unique identifier for the bulk order associated with this card. Only applicable to physical cards that are part of a bulk shipment',
        example: '5e9483eb-8103-4e16-9794-2106111b2eca',
      }),
    replacement_for: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'If the card is a replacement for another card, the globally unique identifier for the card that was replaced.',
        example: '5e9483eb-8103-4e16-9794-2106111b2eca',
      }),
    cardholder_currency: z
      .string()
      .exactOptional()
      .openapi({
        description: '3-character alphabetic ISO 4217 code for the currency of the cardholder.',
        example: 'USD',
      }),
    created: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'An RFC 3339 timestamp for when the card was created. UTC time zone.',
        example: '2021-06-28T22:53:15Z',
      }),
    digital_card_art_token: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "Specifies the digital card art to be displayed in the user's digital wallet after tokenization. This artwork must be approved by Mastercard and configured by Lithic to use.",
        example: '5e9483eb-8103-4e16-9794-2106111b2eca',
      }),
    exp_month: z
      .string()
      .length(2)
      .exactOptional()
      .openapi({ description: 'Two digit (MM) expiry month.', example: '06' }),
    exp_year: z
      .string()
      .length(4)
      .exactOptional()
      .openapi({ description: 'Four digit (yyyy) expiry year.', example: '2027' }),
    funding: z
      .xor([z.null().nullable(), FundingAccountSchema])
      .openapi({ description: 'Deprecated: Funding account for the card.' }),
    hostname: z
      .string()
      .exactOptional()
      .openapi({
        description: "Hostname of card's locked merchant (will be empty if not applicable).",
      }),
    last_four: z
      .string()
      .length(4)
      .openapi({ description: 'Last four digits of the card number.' }),
    memo: z
      .string()
      .exactOptional()
      .openapi({ description: 'Friendly name to identify the card.', example: 'New Card' }),
    network_program_token: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "Globally unique identifier for the card's network program. Null if the card is not associated with a network program. Currently applicable to Visa cards participating in Account Level Management only",
        example: '5e9483eb-8103-4e16-9794-2106111b2eca',
      }),
    pending_commands: z
      .array(z.string())
      .exactOptional()
      .openapi({
        description:
          'Indicates if there are offline PIN changes pending card interaction with an offline PIN terminal. Possible commands are: CHANGE_PIN, UNBLOCK_PIN. Applicable only to cards issued in markets supporting offline PINs.',
      }),
    pin_status: z
      .enum(['OK', 'BLOCKED', 'NOT_SET'])
      .openapi({
        description:
          'Indicates if a card is blocked due a PIN status issue (e.g. excessive incorrect attempts).',
      }),
    product_id: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Only applicable to cards of type `PHYSICAL`. This must be configured with Lithic before use. Specifies the configuration (i.e., physical card art) that the card should be manufactured with.',
        example: '1',
      }),
    spend_limit: z
      .int()
      .openapi({
        description:
          'Amount (in cents) to limit approved authorizations (e.g. 100000 would be a $1,000 limit). Transaction requests above the spend limit will be declined.',
        example: 1000,
      }),
    spend_limit_duration: SpendLimitDurationSchema,
    state: z
      .enum(['CLOSED', 'OPEN', 'PAUSED', 'PENDING_ACTIVATION', 'PENDING_FULFILLMENT'])
      .openapi({
        description:
          'Card state values: * `CLOSED` - Card will no longer approve authorizations. Closing a card cannot be undone. * `OPEN` - Card will approve authorizations (if they match card and account parameters). * `PAUSED` - Card will decline authorizations, but can be resumed at a later time. * `PENDING_FULFILLMENT` - The initial state for cards of type `PHYSICAL`. The card is provisioned pending manufacturing and fulfillment. Cards in this state can accept authorizations for e-commerce purchases, but not for "Card Present" purchases where the physical card itself is present. * `PENDING_ACTIVATION` - At regular intervals, cards of type `PHYSICAL` in state `PENDING_FULFILLMENT` are sent to the card production warehouse and updated to state `PENDING_ACTIVATION`. Similar to `PENDING_FULFILLMENT`, cards in this state can be used for e-commerce transactions or can be added to mobile wallets. API clients should update the card\'s state to `OPEN` only after the cardholder confirms receipt of the card. In sandbox, the same daily batch fulfillment occurs, but no cards are actually manufactured.',
      }),
    substatus: z
      .enum([
        'LOST',
        'COMPROMISED',
        'DAMAGED',
        'END_USER_REQUEST',
        'ISSUER_REQUEST',
        'NOT_ACTIVE',
        'SUSPICIOUS_ACTIVITY',
        'INTERNAL_REVIEW',
        'EXPIRED',
        'UNDELIVERABLE',
        'OTHER',
      ])
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "Card state substatus values: * `LOST` - The physical card is no longer in the cardholder's possession due to being lost or never received by the cardholder. * `COMPROMISED` - Card information has been exposed, potentially leading to unauthorized access. This may involve physical card theft, cloning, or online data breaches. * `DAMAGED` - The physical card is not functioning properly, such as having chip failures or a demagnetized magnetic stripe. * `END_USER_REQUEST` - The cardholder requested the closure of the card for reasons unrelated to fraud or damage, such as switching to a different product or closing the account. * `ISSUER_REQUEST` - The issuer closed the card for reasons unrelated to fraud or damage, such as account inactivity, product or policy changes, or technology upgrades. * `NOT_ACTIVE` - The card hasn’t had any transaction activity for a specified period, applicable to statuses like `PAUSED` or `CLOSED`. * `SUSPICIOUS_ACTIVITY` - The card has one or more suspicious transactions or activities that require review. This can involve prompting the cardholder to confirm legitimate use or report confirmed fraud. * `INTERNAL_REVIEW` - The card is temporarily paused pending further internal review. * `EXPIRED` - The card has expired and has been closed without being reissued. * `UNDELIVERABLE` - The card cannot be delivered to the cardholder and has been returned. * `OTHER` - The reason for the status does not fall into any of the above categories. A comment can be provided to specify the reason.",
      }),
    comment: z
      .string()
      .exactOptional()
      .openapi({ description: 'Additional context or information related to the card.' }),
    tags: TagsSchema,
    token: z
      .string()
      .openapi({
        description: 'Globally unique identifier.',
        example: '7ef7d65c-9023-4da3-b113-3b8583fd7951',
      }),
    type: z
      .enum(['MERCHANT_LOCKED', 'PHYSICAL', 'SINGLE_USE', 'VIRTUAL', 'UNLOCKED', 'DIGITAL_WALLET'])
      .openapi({
        description:
          'Card types: * `VIRTUAL` - Card will authorize at any merchant and can be added to a digital wallet like Apple Pay or Google Pay (if the card program is digital wallet-enabled). * `PHYSICAL` - Manufactured and sent to the cardholder. We offer white label branding, credit, ATM, PIN debit, chip/EMV, NFC and magstripe functionality. * `SINGLE_USE` - Card is closed upon first successful authorization. * `MERCHANT_LOCKED` - Card is locked to the first merchant that successfully authorizes the card. * `UNLOCKED` - *[Deprecated]* Similar behavior to VIRTUAL cards, please use VIRTUAL instead. * `DIGITAL_WALLET` - *[Deprecated]* Similar behavior to VIRTUAL cards, please use VIRTUAL instead.',
      }),
  })
  .openapi({
    description: 'Card details without PCI information',
    required: [
      'account_token',
      'card_program_token',
      'created',
      'funding',
      'last_four',
      'pin_status',
      'spend_limit',
      'spend_limit_duration',
      'state',
      'tags',
      'token',
      'type',
    ],
  })
  .openapi('NonPciCardResponse')

const CarrierSchema = z
  .object({
    qr_code_url: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'QR code URL to display on the card carrier. The `qr_code_url` field requires your domain to be allowlisted by Lithic before use. Contact Support to configure your QR code domain',
      }),
  })
  .openapi({ required: [] })
  .openapi('Carrier')

const ShippingAddressSchema = z
  .object({
    address1: z
      .string()
      .min(1)
      .max(40)
      .openapi({ description: 'Valid USPS routable address.', example: '5 Broad Street' }),
    address2: z
      .string()
      .min(1)
      .max(40)
      .exactOptional()
      .openapi({ description: 'Unit number (if applicable).', example: 'Unit 25A' }),
    city: z.string().min(1).max(30).openapi({ description: 'City', example: 'NEW YORK' }),
    country: z
      .string()
      .length(3)
      .openapi({
        description: 'Uppercase ISO 3166-1 alpha-3 three character abbreviation.',
        example: 'USA',
      }),
    email: z
      .string()
      .min(5)
      .max(50)
      .exactOptional()
      .openapi({
        description:
          'Email address to be contacted for expedited shipping process purposes. Required if `shipping_method` is `EXPEDITED`.',
        example: 'johnny@appleseed.com',
      }),
    first_name: z
      .string()
      .min(1)
      .max(24)
      .openapi({
        description:
          "Customer's first name. This will be the first name printed on the physical card. The combined length of `first_name` and `last_name` may not exceed 25 characters.",
        example: 'Michael',
      }),
    last_name: z
      .string()
      .min(1)
      .max(24)
      .openapi({
        description:
          "Customer's surname (family name). This will be the last name printed on the physical card. The combined length of `first_name` and `last_name` may not exceed 25 characters.",
        example: 'Bluth',
      }),
    line2_text: z
      .string()
      .min(0)
      .max(26)
      .exactOptional()
      .openapi({
        description:
          'Text to be printed on line two of the physical card. Use of this field requires additional permissions.',
        example: 'The Bluth Company',
      }),
    phone_number: z
      .string()
      .min(8)
      .max(16)
      .exactOptional()
      .openapi({
        description:
          "Cardholder's phone number in E.164 format to be contacted for expedited shipping process purposes. Required if `shipping_method` is `EXPEDITED`.",
        example: '+15555555555',
      }),
    postal_code: z
      .string()
      .min(1)
      .max(12)
      .openapi({
        description:
          'Postal code (formerly zipcode). For US addresses, either five-digit postal code or nine-digit postal code (ZIP+4) using the format 12345-1234.',
        example: '10001-1809',
      }),
    state: z
      .string()
      .min(0)
      .max(24)
      .openapi({
        description:
          'Uppercase ISO 3166-2 two character abbreviation for US and CA. Optional with a limit of 24 characters for other countries.',
        example: 'NY',
      }),
  })
  .openapi({
    required: ['address1', 'city', 'country', 'first_name', 'last_name', 'postal_code', 'state'],
  })
  .openapi('ShippingAddress')

const PciCardResponseSchema = NonPciCardResponseSchema.and(
  z
    .object({
      pan: z
        .string()
        .length(16)
        .exactOptional()
        .openapi({
          description:
            'Primary Account Number (PAN) (i.e. the card number). Customers must be PCI compliant to have PAN returned as a field in production. Please contact https://support.lithic.com/ for questions.',
          example: '4111111289144142',
        }),
      cvv: z
        .string()
        .min(3)
        .max(4)
        .exactOptional()
        .openapi({
          description:
            'Three or four digit CVV printed on the card. Amex cards use four digit CVVs',
          example: '776',
        }),
    })
    .openapi({ examples: [{ pan: '4111111289144142', cvv: '776' }], required: [] }),
)
  .openapi({
    description: 'Card details with potentially PCI sensitive information for Enterprise customers',
  })
  .openapi('PciCardResponse')

const TagsPatchSchema = z
  .record(z.string(), z.string().max(500).nullable())
  .openapi({
    title: 'Tags Patch',
    description:
      "Key-value pairs to merge into a resource's tags. Supplied keys are added or overwritten, a key with a `null` value is removed, and omitted keys remain unchanged",
    example: { 'risk-level': 'high', 'legacy-program': null },
  })
  .openapi('TagsPatch')

const FinancialAccountBalanceSchema = z
  .object({
    available_amount: z
      .int()
      .openapi({
        description:
          "Funds available for spend in the currency's smallest unit (e.g., cents for USD)",
      }),
    created: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'Date and time for when the balance was first created.' }),
    currency: z
      .string()
      .openapi({
        description: '3-character alphabetic ISO 4217 code for the local currency of the balance.',
      }),
    token: z
      .uuid()
      .openapi({
        description:
          'Globally unique identifier for the financial account that holds this balance.',
        example: '3fa85f64-5717-4562-b3fc-2c963f66afa6',
      }),
    type: z
      .enum(['ISSUING', 'OPERATING', 'RESERVE', 'SECURITY'])
      .openapi({ description: 'Type of financial account.' }),
    last_transaction_event_token: z
      .uuid()
      .nullable()
      .openapi({
        description:
          'Globally unique identifier for the last financial transaction event that impacted this balance.',
      }),
    last_transaction_token: z
      .uuid()
      .nullable()
      .openapi({
        description:
          'Globally unique identifier for the last financial transaction that impacted this balance.',
      }),
    pending_amount: z
      .int()
      .openapi({
        description:
          "Funds not available for spend due to card authorizations or pending ACH release. Shown in the currency's smallest unit (e.g., cents for USD).",
      }),
    total_amount: z
      .int()
      .openapi({
        description:
          "The sum of available and pending balance in the currency's smallest unit (e.g., cents for USD).",
      }),
    updated: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'Date and time for when the balance was last updated.' }),
  })
  .openapi({
    title: 'Financial Account Balance',
    description: 'Balance of a Financial Account',
    required: [
      'available_amount',
      'created',
      'currency',
      'token',
      'type',
      'last_transaction_event_token',
      'last_transaction_token',
      'pending_amount',
      'total_amount',
      'updated',
    ],
  })
  .openapi('FinancialAccountBalance')

const FinancialAccountTransactionSchema = z
  .object({
    category: z
      .enum(['ACH', 'CARD', 'INTERNAL', 'TRANSFER'])
      .openapi({
        description:
          'Status types:\n\n* `CARD` - Issuing card transaction.\n* `ACH` - Transaction over ACH.\n* `INTERNAL` - Transaction for internal adjustment.\n* `TRANSFER` - Internal transfer of funds between financial accounts in your program.\n',
      }),
    created: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'Date and time when the financial transaction first occurred. UTC time zone.',
      }),
    currency: z
      .string()
      .openapi({
        description:
          '3-character alphabetic ISO 4217 code for the settling currency of the transaction.',
      }),
    descriptor: z
      .string()
      .openapi({
        description:
          'A string that provides a description of the financial transaction; may be useful to display to users.',
      }),
    events: z
      .array(FinancialEventSchema)
      .openapi({
        description:
          'A list of all financial events that have modified this financial transaction.',
      }),
    pending_amount: z
      .int()
      .openapi({
        description:
          "Pending amount of the transaction in the currency's smallest unit (e.g., cents), including any acquirer fees.\n\nThe value of this field will go to zero over time once the financial transaction is settled.\n",
      }),
    result: z
      .enum(['APPROVED', 'DECLINED'])
      .openapi({
        description:
          'APPROVED transactions were successful while DECLINED transactions were declined by user, Lithic, or the network.',
      }),
    settled_amount: z
      .int()
      .openapi({
        description:
          "Amount of the transaction that has been settled in the currency's smallest unit (e.g., cents), including any acquirer fees. This may change over time.",
      }),
    status: z
      .enum(['DECLINED', 'EXPIRED', 'PENDING', 'RETURNED', 'SETTLED', 'VOIDED'])
      .openapi({
        description:
          'Status types:\n\n* `DECLINED` - The transaction was declined.\n* `EXPIRED` - The authorization as it has passed its expiration time. Card transaction only.\n* `PENDING` - The transaction is expected to settle.\n* `RETURNED` - The transaction has been returned.\n* `SETTLED` - The transaction is completed.\n* `VOIDED` - The transaction was voided. Card transaction only.\n',
      }),
    token: z.uuid().openapi({ description: 'Globally unique identifier.' }),
    updated: z.iso
      .datetime({ offset: true })
      .openapi({
        description:
          'Date and time when the financial transaction was last updated. UTC time zone.',
      }),
  })
  .openapi({
    required: [
      'category',
      'created',
      'currency',
      'descriptor',
      'events',
      'pending_amount',
      'result',
      'settled_amount',
      'status',
      'token',
      'updated',
    ],
  })
  .openapi('FinancialAccountTransaction')

const WebPushProvisioningResponseHeaderSchema = z
  .object({
    kid: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The ID for the JWS Public Key of the key pair used to generate the signature.',
        example: '8dc7aed4-29e3-41e4-9cdb-673a05e6615c',
      }),
  })
  .openapi({ required: [] })
  .openapi('WebPushProvisioningResponseHeader')

const WebPushProvisioningResponseJwsSchema = z
  .object({
    header: WebPushProvisioningResponseHeaderSchema.exactOptional().openapi({
      description:
        "JWS unprotected headers containing header parameters that aren't integrity-protected by the JWS signature.",
    }),
    protected: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'Base64url encoded JWS protected headers containing the header parameters that are integrity-protected by the JWS signature.',
        example: 'eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCJ9',
      }),
    payload: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Base64url encoded JSON object containing the provisioning payload.',
        example: 'eyJhbGciOiJSUzI1NiIsInR5cCI6IkpXVCJ9',
      }),
    signature: z
      .string()
      .exactOptional()
      .openapi({
        description: 'Base64url encoded signature of the JWS object.',
        example: 'SflKxwRJSMeKKF2QT4fwpMeJf36POk6yJV_adQssw5c',
      }),
  })
  .openapi({ required: [] })
  .openapi('WebPushProvisioningResponseJws')

const AppleWebPushProvisioningResponseSchema = z
  .object({
    jws: WebPushProvisioningResponseJwsSchema.openapi({
      description: "JWS object required for handoff to Apple's script.",
    }),
    state: z
      .string()
      .openapi({
        description: 'A unique identifier for the JWS object.',
        example: '3cc4c292-727b-4ca8-b9a8-f96c15485f4e',
      }),
  })
  .openapi({ required: ['jws', 'state'] })
  .openapi('AppleWebPushProvisioningResponse')

const GoogleWebPushProvisioningResponseSchema = z
  .object({
    google_opc: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A base64 encoded and encrypted payload representing card data for the Google Pay UWPP FPAN flow.',
        example: 'WW91ciBTdHJpbmcgSGVyZQ==',
      }),
    tsp_opc: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A base64 encoded and encrypted payload representing card data for the Google Pay UWPP tokenization flow.',
        example: 'WW91ciBTdHJpbmcgSGVyZQ==',
      }),
  })
  .openapi({ required: [] })
  .refine(
    (val) =>
      !z
        .object({ jws: z.any() })
        .openapi({ required: ['jws'] })
        .safeParse(val).success,
  )
  .openapi('GoogleWebPushProvisioningResponse')

const WebPushProvisioningResponseSchema = z
  .xor([AppleWebPushProvisioningResponseSchema, GoogleWebPushProvisioningResponseSchema])
  .openapi('WebPushProvisioningResponse')

