const DisputeV1Schema = z
  .object({
    amount: z
      .int()
      .openapi({
        description: 'Amount under dispute. May be different from the original transaction amount.',
      }),
    arbitration_date: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({ description: 'Date dispute entered arbitration.' }),
    created: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'Timestamp of when first Dispute was reported.' }),
    customer_filed_date: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({
        description: 'Date that the dispute was filed by the customer making the dispute.',
      }),
    customer_note: z
      .string()
      .max(10000)
      .nullable()
      .openapi({ description: 'End customer description of the reason for the dispute.' }),
    network_claim_ids: z
      .xor([z.array(z.string()), z.null().nullable()])
      .openapi({ description: 'Unique identifiers for the dispute from the network.' }),
    network_filed_date: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({ description: 'Date that the dispute was submitted to the network.' }),
    network_reason_code: z
      .string()
      .nullable()
      .openapi({ description: 'Network reason code used to file the dispute.' }),
    prearbitration_date: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({ description: 'Date dispute entered pre-arbitration.' }),
    primary_claim_id: z
      .string()
      .nullable()
      .openapi({
        description:
          'Unique identifier for the dispute from the network. If there are multiple, this will be the first claim id set by the network',
      }),
    reason: z
      .enum([
        'ATM_CASH_MISDISPENSE',
        'CANCELLED',
        'DUPLICATED',
        'FRAUD_CARD_NOT_PRESENT',
        'FRAUD_CARD_PRESENT',
        'FRAUD_OTHER',
        'GOODS_SERVICES_NOT_AS_DESCRIBED',
        'GOODS_SERVICES_NOT_RECEIVED',
        'INCORRECT_AMOUNT',
        'MISSING_AUTH',
        'OTHER',
        'PROCESSING_ERROR',
        'RECURRING_TRANSACTION_NOT_CANCELLED',
        'REFUND_NOT_PROCESSED',
      ])
      .openapi({
        description:
          'Dispute reason:\n* `ATM_CASH_MISDISPENSE`: ATM cash misdispense.\n* `CANCELLED`: Transaction was cancelled by the customer.\n* `DUPLICATED`: The transaction was a duplicate.\n* `FRAUD_CARD_NOT_PRESENT`: Fraudulent transaction, card not present.\n* `FRAUD_CARD_PRESENT`: Fraudulent transaction, card present.\n* `FRAUD_OTHER`: Fraudulent transaction, other types such as questionable merchant activity.\n* `GOODS_SERVICES_NOT_AS_DESCRIBED`: The goods or services were not as described.\n* `GOODS_SERVICES_NOT_RECEIVED`: The goods or services were not received.\n* `INCORRECT_AMOUNT`: The transaction amount was incorrect.\n* `MISSING_AUTH`: The transaction was missing authorization.\n* `OTHER`: Other reason.\n* `PROCESSING_ERROR`: Processing error.\n* `REFUND_NOT_PROCESSED`: The refund was not processed.\n* `RECURRING_TRANSACTION_NOT_CANCELLED`: The recurring transaction was not cancelled.\n',
      }),
    representment_date: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({ description: 'Date the representment was received.' }),
    resolution_date: z.iso
      .datetime({ offset: true })
      .nullable()
      .openapi({ description: 'Date that the dispute was resolved.' }),
    resolution_note: z
      .string()
      .max(10000)
      .nullable()
      .openapi({ description: 'Note by Dispute team on the case resolution.' }),
    resolution_reason: z
      .union([
        z.literal('CASE_LOST'),
        z.literal('NETWORK_REJECTED'),
        z.literal('NO_DISPUTE_RIGHTS_3DS'),
        z.literal('NO_DISPUTE_RIGHTS_BELOW_THRESHOLD'),
        z.literal('NO_DISPUTE_RIGHTS_CONTACTLESS'),
        z.literal('NO_DISPUTE_RIGHTS_HYBRID'),
        z.literal('NO_DISPUTE_RIGHTS_MAX_CHARGEBACKS'),
        z.literal('NO_DISPUTE_RIGHTS_OTHER'),
        z.literal('PAST_FILING_DATE'),
        z.literal('PREARBITRATION_REJECTED'),
        z.literal('PROCESSOR_REJECTED_OTHER'),
        z.literal('REFUNDED'),
        z.literal('REFUNDED_AFTER_CHARGEBACK'),
        z.literal('WITHDRAWN'),
        z.literal('WON_ARBITRATION'),
        z.literal('WON_FIRST_CHARGEBACK'),
        z.literal('WON_PREARBITRATION'),
        z.literal(null),
      ])
      .nullable()
      .openapi({
        description:
          'Reason for the dispute resolution:\n* `CASE_LOST`: This case was lost at final arbitration.\n* `NETWORK_REJECTED`: Network rejected.\n* `NO_DISPUTE_RIGHTS_3DS`: No dispute rights, 3DS.\n* `NO_DISPUTE_RIGHTS_BELOW_THRESHOLD`: No dispute rights, below threshold.\n* `NO_DISPUTE_RIGHTS_CONTACTLESS`: No dispute rights, contactless.\n* `NO_DISPUTE_RIGHTS_HYBRID`: No dispute rights, hybrid.\n* `NO_DISPUTE_RIGHTS_MAX_CHARGEBACKS`: No dispute rights, max chargebacks.\n* `NO_DISPUTE_RIGHTS_OTHER`: No dispute rights, other.\n* `PAST_FILING_DATE`: Past filing date.\n* `PREARBITRATION_REJECTED`: Prearbitration rejected.\n* `PROCESSOR_REJECTED_OTHER`: Processor rejected, other.\n* `REFUNDED`: Refunded.\n* `REFUNDED_AFTER_CHARGEBACK`: Refunded after chargeback.\n* `WITHDRAWN`: Withdrawn.\n* `WON_ARBITRATION`: Won arbitration.\n* `WON_FIRST_CHARGEBACK`: Won first chargeback.\n* `WON_PREARBITRATION`: Won prearbitration.\n',
      }),
    status: z
      .enum([
        'ARBITRATION',
        'CASE_CLOSED',
        'CASE_WON',
        'NEW',
        'PENDING_CUSTOMER',
        'PREARBITRATION',
        'REPRESENTMENT',
        'SUBMITTED',
      ])
      .openapi({
        description:
          'Status types:\n* `NEW` - New dispute case is opened.\n* `PENDING_CUSTOMER` - Lithic is waiting for customer to provide more information.\n* `SUBMITTED` - Dispute is submitted to the card network.\n* `REPRESENTMENT` - Case has entered second presentment.\n* `PREARBITRATION` - Case has entered prearbitration.\n* `ARBITRATION` - Case has entered arbitration.\n* `CASE_WON` - Case was won and credit will be issued.\n* `CASE_CLOSED` - Case was lost or withdrawn.\n',
      }),
    token: z.uuid().openapi({ description: 'Globally unique identifier.' }),
    transaction_token: z
      .uuid()
      .openapi({
        description:
          'The transaction that is being disputed. A transaction can only be disputed once but may have multiple dispute cases.',
      }),
  })
  .openapi({
    title: 'Dispute',
    description: 'Dispute.',
    required: [
      'amount',
      'arbitration_date',
      'created',
      'customer_filed_date',
      'customer_note',
      'network_claim_ids',
      'network_filed_date',
      'network_reason_code',
      'prearbitration_date',
      'primary_claim_id',
      'reason',
      'representment_date',
      'resolution_date',
      'resolution_note',
      'resolution_reason',
      'status',
      'token',
      'transaction_token',
    ],
  })
  .openapi('DisputeV1')

