const TierScheduleEntrySchema = z
  .object({
    tier_name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Name of a tier contained in the credit product. Mutually exclusive with tier_rates',
      }),
    effective_date: z.iso
      .date()
      .openapi({ description: 'Date the tier should be effective in YYYY-MM-DD format' }),
    tier_rates: z
      .looseObject({})
      .superRefine((o, ctx) => {
        const regex = new RegExp('^.*$')
        const Schema = CategoryTierSchema
        for (const [k, val] of Object.entries(o)) {
          if (!regex.test(k)) {
            continue
          }
          const result = Schema.safeParse(val)
          if (!result.success) {
            for (const issue of result.error.issues) {
              ctx.addIssue({ ...issue, path: [k, ...issue.path] })
            }
          }
        }
      })
      .nullable()
      .exactOptional()
      .openapi({ description: 'Custom rates per category.  Mutually exclusive with tier_name' }),
    penalty_rates: z
      .looseObject({})
      .superRefine((o, ctx) => {
        const regex = new RegExp('^.*$')
        const Schema = CategoryTierSchema
        for (const [k, val] of Object.entries(o)) {
          if (!regex.test(k)) {
            continue
          }
          const result = Schema.safeParse(val)
          if (!result.success) {
            for (const issue of result.error.issues) {
              ctx.addIssue({ ...issue, path: [k, ...issue.path] })
            }
          }
        }
      })
      .nullable()
      .exactOptional()
      .openapi({ description: 'Custom rates per category for penalties' }),
    credit_product_token: z
      .string()
      .openapi({ description: 'Globally unique identifier for a credit product' }),
  })
  .openapi({
    title: 'Tier Schedule Entry',
    description: 'Entry in the Tier Schedule of an account',
    required: ['effective_date', 'credit_product_token'],
  })
  .openapi('TierScheduleEntry')

