    'CVC_MISMATCH',
    'CARD_EXPIRY_MONTH_MISMATCH',
    'CARD_EXPIRY_YEAR_MISMATCH',
    'CARD_INVALID_STATE',
    'CUSTOMER_RED_PATH',
