const CreateQueueRequestSchema = z
  .object({
    name: z.string().openapi({ description: 'Human-readable name of the queue' }),
    description: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Optional description of the queue' }),
    allowed_resolutions: z
      .array(z.string().min(1))
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Resolutions that can be recorded on cases in this queue. Omit or send `null` to\nuse the default list. Values are free-form labels and must be non-empty and unique',
      }),
  })
  .openapi({
    title: 'Create Queue Request',
    description: 'Parameters for creating a queue',
    required: ['name'],
  })
  .openapi('CreateQueueRequest')

const UpdateQueueRequestSchema = z
  .object({
    name: z.string().exactOptional().openapi({ description: 'New name for the queue' }),
    description: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'New description for the queue, or `null` to clear it' }),
    allowed_resolutions: z
      .array(z.string().min(1))
      .min(1)
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'New list of resolutions that can be recorded on cases in this queue, or `null` to\nrevert to the default list. Values are free-form labels and must be non-empty and\nunique. Changing the list only affects what is selectable going forward; the\n`resolution` already stored on a case is preserved as-is',
      }),
  })
  .openapi({
    title: 'Update Queue Request',
    description:
      'Parameters for updating a queue. All fields are optional; omitted fields are left unchanged',
    required: [],
  })
  .openapi('UpdateQueueRequest')

const TransferSchema = z
  .object({
    category: z
      .literal('TRANSFER')
      .exactOptional()
      .openapi({
        description:
          'Status types:\n* `TRANSFER` - Internal transfer of funds between financial accounts in your program.\n',
      }),
    created: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({ description: 'Date and time when the transfer occurred. UTC time zone.' }),
    currency: z
      .string()
      .exactOptional()
      .openapi({
        description:
          '3-character alphabetic ISO 4217 code for the settling currency of the transaction.',
      }),
    descriptor: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A string that provides a description of the transfer; may be useful to display to users.',
      }),
    events: z
      .array(FinancialEventSchema)
      .exactOptional()
      .openapi({ description: 'A list of all financial events that have modified this trasnfer.' }),
    from_balance: z
      .array(BalanceSchema)
      .exactOptional()
      .openapi({ description: 'The updated balance of the sending financial account.' }),
    pending_amount: z
      .int()
      .exactOptional()
      .openapi({
        description:
          "Pending amount of the transaction in the currency's smallest unit (e.g., cents), including any acquirer fees.\nThe value of this field will go to zero over time once the financial transaction is settled.\n",
      }),
    result: z
      .enum(['APPROVED', 'DECLINED'])
      .exactOptional()
      .openapi({
        description:
          'APPROVED transactions were successful while DECLINED transactions were declined by user, Lithic, or the network.',
      }),
    settled_amount: z
      .int()
      .exactOptional()
      .openapi({
        description:
          "Amount of the transaction that has been settled in the currency's smallest unit (e.g., cents).",
      }),
    status: z
      .enum(['DECLINED', 'EXPIRED', 'PENDING', 'SETTLED', 'VOIDED'])
      .exactOptional()
      .openapi({
        description:
          'Status types:\n* `DECLINED` - The transfer was declined.\n* `EXPIRED` - The transfer was held in pending for too long and expired.\n* `PENDING` - The transfer is pending release from a hold.\n* `SETTLED` - The transfer is completed.\n* `VOIDED` - The transfer was reversed before it settled.\n',
      }),
    to_balance: z
      .array(BalanceSchema)
      .exactOptional()
      .openapi({ description: 'The updated balance of the receiving financial account.' }),
    token: z
      .uuid()
      .exactOptional()
      .openapi({ description: 'Globally unique identifier for the transfer event.' }),
    updated: z.iso
      .datetime({ offset: true })
      .exactOptional()
      .openapi({
        description:
          'Date and time when the financial transaction was last updated. UTC time zone.',
      }),
  })
  .openapi({ required: [] })
  .openapi('Transfer')

