const FundingEventSettlementSchema = z
  .object({
    settled_gross_amount: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64' }),
    network_settlement_date: z.iso.date().openapi({ example: '2024-01-01' }),
  })
  .openapi({
    title: 'Funding Event Settlement',
    required: ['settled_gross_amount', 'network_settlement_date'],
  })
  .openapi('FundingEventSettlement')

const FundingEventResponseSchema = z
  .object({
    token: z
      .uuid()
      .openapi({ description: 'Unique token ID', example: 'b68b7424-aa69-4cbc-a946-30d90181b621' }),
    collection_tokens: z
      .array(z.uuid().openapi({ example: 'b68b7424-aa69-4cbc-a946-30d90181b621' }))
      .openapi({
        description:
          'IDs of collections, further information can be gathered from the appropriate collection API based on collection_resource_type',
      }),
    previous_high_watermark: z.iso
      .datetime({ offset: true })
      .openapi({
        description: 'Time of the previous high watermark',
        example: '2024-01-01T00:00:00Z',
      }),
    high_watermark: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'Time of the high watermark', example: '2024-01-01T00:00:00Z' }),
    collection_resource_type: z
      .enum(['BOOK_TRANSFER', 'PAYMENT'])
      .openapi({ description: 'Collection resource type', example: 'PAYMENT' }),
    network_settlement_summary: z
      .array(FundingEventSettlementSchema)
      .openapi({ description: 'Network settlement summary breakdown by network settlement date' }),
    created: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'Time of the creation', example: '2024-01-01T00:00:00Z' }),
    updated: z.iso
      .datetime({ offset: true })
      .openapi({ description: 'Time of the update', example: '2024-01-01T00:00:00Z' }),
  })
  .openapi({
    title: 'Funding Event Response',
    required: [
      'token',
      'previous_high_watermark',
      'high_watermark',
      'collection_resource_type',
      'created',
      'updated',
      'network_settlement_summary',
      'collection_tokens',
    ],
  })
  .openapi('FundingEventResponse')

