const CardUpdatedSchema = z
  .object({
    previous_fields: z
      .looseObject({})
      .openapi({
        description: 'The previous values of the fields that were updated.',
        example: { state: 'PAUSED' },
      }),
    state: z.string().openapi({ description: 'The current state of the card.', example: 'OPEN' }),
    card_token: z
      .uuid()
      .openapi({
        description: 'The token of the card that was updated.',
        example: '00000000-0000-0000-0000-000000000000',
      }),
  })
  .openapi({
    title: 'Card Updated',
    examples: [
      {
        previous_fields: { state: 'PAUSED' },
        state: 'OPEN',
        card_token: '00000000-0000-0000-0000-000000000000',
      },
    ],
    required: ['previous_fields', 'state', 'card_token'],
  })
  .openapi('CardUpdated')

