const ThreeDsDecisioningSchema = z
  .object({
    three_ds_authentication_decision: z
      .enum(['APPROVE', 'DECLINE', 'CHALLENGE_REQUESTED'])
      .openapi({
        description:
          '* `APPROVE` - Approve the 3DS Transaction and proceed to Authorization\n* `DECLINE` - Decline the 3DS Transaction ending the transaction\n* `CHALLENGE_REQUESTED` - Conditional Approval for the 3DS Transaction where a follow-up Challenge will be triggered to further authenticate the Cardholder',
      }),
    oob_url: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'URL which may be used in the presentation of a 3DS Challenge UI to the cardholder. This value will be used by the ACS as the OOB App URL. When applicable, this URL may be used for automatic app switching or rendered directly as an element in the Challenge UI.\nThis field is only used with CHALLENGE_REQUESTED decision and when customer orchestrates the 3DS challenge on their own.',
      }),
    exemption_applied: z
      .enum(['TRANSACTION_RISK_ANALYSIS', 'RECURRING_PAYMENT'])
      .exactOptional()
      .openapi({
        description:
          "SCA exemption the card program asserts on an `APPROVE` decision. Ignored for `DECLINE` or `CHALLENGE_REQUESTED`.\n\nWhen `psd2_context` is present in the decisioning request, this field must be set to approve with\nan exemption. The card program would do this when they have their own grounds or knowledge that\noverride Lithic's validation. Lithic passes the value to the ACS to generate the correct ECI and\nauthentication value.\n\nOmit (or send `NONE`) for full SCA with no exemption asserted.\n\n* `TRANSACTION_RISK_ANALYSIS` - Transaction Risk Analysis (TRA); card program has independent fraud scoring that supports frictionless approval\n* `RECURRING_PAYMENT` - Recurring payment with a fixed amount to the same payee; card program has explicit mandate data",
      }),
  })
  .openapi({
    title: '3DS Decision Response object',
    description:
      'Information on whether the Authentication should be approved, declined or challenged.',
    required: ['three_ds_authentication_decision'],
  })
  .openapi('ThreeDsDecisioning')

