export const getV2AuthRulesRoute = createRoute({
  method: 'get',
  path: '/v2/auth_rules',
  tags: ['Auth Rules'],
  summary: 'List rules',
  description: 'Lists V2 Auth rules',
  operationId: 'getAuthRules',
  request: {
    query: z.object({
      ending_before: EndingBefore2ParamsSchema,
      page_size: PageSize2ParamsSchema,
      starting_after: StartingAfter2ParamsSchema,
      card_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            name: 'card_token',
            in: 'query',
            description: 'Only return Auth Rules that are bound to the provided card token.',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      account_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            name: 'account_token',
            in: 'query',
            description: 'Only return Auth Rules that are bound to the provided account token.',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      business_account_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            name: 'business_account_token',
            in: 'query',
            description:
              'Only return Auth Rules that are bound to the provided business account token.',
            schema: { type: 'string', format: 'uuid' },
            required: false,
          },
        }),
      scope: z
        .enum(['PROGRAM', 'ACCOUNT', 'BUSINESS_ACCOUNT', 'CARD', 'ANY'])
        .exactOptional()
        .openapi({
          param: {
            name: 'scope',
            in: 'query',
            description:
              'Only return Auth Rules that are bound to the provided scope. When no token is provided, `CARD` also returns Auth Rules that include a `CARD_TAG` entity.',
            schema: {
              enum: ['PROGRAM', 'ACCOUNT', 'BUSINESS_ACCOUNT', 'CARD', 'ANY'],
              type: 'string',
            },
            required: false,
          },
        }),
      event_stream: EventStreamSchema.openapi({
        param: {
          name: 'event_stream',
          in: 'query',
          description:
            'Deprecated: Use event_streams instead. Only return Auth rules that are executed during the provided event stream.',
          deprecated: true,
          schema: { $ref: '#/components/schemas/event-stream' },
          required: false,
        },
      }).exactOptional(),
      event_streams: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(EventStreamSchema),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'event_streams',
            in: 'query',
            explode: false,
            description:
              'Only return Auth rules that are executed during any of the provided event streams. If event_streams and event_stream are specified, the values will be combined.',
            style: 'form',
            schema: { type: 'array', items: { $ref: '#/components/schemas/event-stream' } },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Auth Rules',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(AuthRuleSchema),
              has_more: z
                .boolean()
                .openapi({
                  description:
                    'Indicates whether there are more Auth Rules to be retrieved by paging through the results.',
                }),
            })
            .openapi({ required: ['data', 'has_more'] }),
        },
      },
    },
    400: ResponsesBadRequestResponse,
    404: ResponsesNotFoundResponse,
  },
})

