export const postV1CardsRoute = createRoute({
  method: 'post',
  path: '/v1/cards',
  tags: ['Card'],
  summary: 'Create card',
  description:
    'Create a new virtual or physical card. Parameters `shipping_address` and `product_id` only apply to physical cards.\n',
  operationId: 'postCards',
  request: {
    headers: z.object({ 'Idempotency-Key': IdempotencyKeyParamsSchema }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              account_token: z
                .uuid()
                .exactOptional()
                .openapi({
                  description:
                    'Globally unique identifier for the account that the card will be associated with. Required for programs enrolling users using the [/account\\_holders endpoint](https://docs.lithic.com/docs/account-holders-kyc). See [Managing Your Program](doc:managing-your-program) for more information.\n',
                }),
              card_program_token: z
                .uuid()
                .exactOptional()
                .openapi({
                  description:
                    "For card programs with more than one BIN range. This must be configured with Lithic before use. Identifies the card program/BIN range under which to create the card. If omitted, will utilize the program's default `card_program_token`. In Sandbox, use 00000000-0000-0000-1000-000000000000 and 00000000-0000-0000-2000-000000000000 to test creating cards on specific card programs.",
                  example: '5e9483eb-8103-4e16-9794-2106111b2eca',
                }),
              bulk_order_token: z
                .uuid()
                .exactOptional()
                .openapi({
                  description:
                    'Globally unique identifier for an existing bulk order to associate this card with. When specified, the card will be added to the bulk order for batch shipment. Only applicable to cards of type PHYSICAL',
                  example: '5e9483eb-8103-4e16-9794-2106111b2eca',
                }),
              carrier: CarrierSchema.exactOptional(),
              digital_card_art_token: z
                .uuid()
                .exactOptional()
                .openapi({
                  description:
                    'Specifies the digital card art to be displayed in the user’s digital wallet after tokenization. This artwork must be approved by Mastercard and configured by Lithic to use. See [Flexible Card Art Guide](https://docs.lithic.com/docs/about-digital-wallets#flexible-card-art).',
                  example: '5e9483eb-8103-4e16-9794-2106111b2eca',
                }),
              exp_month: z
                .string()
                .length(2)
                .exactOptional()
                .openapi({
                  description:
                    'Two digit (MM) expiry month. If neither `exp_month` nor `exp_year` is provided, an expiration date five years in the future will be generated. Five years is the maximum expiration date.',
                  example: '06',
                }),
              exp_year: z
                .string()
                .length(4)
                .exactOptional()
                .openapi({
                  description:
                    'Four digit (yyyy) expiry year. If neither `exp_month` nor `exp_year` is provided, an expiration date five years in the future will be generated. Five years is the maximum expiration date.',
                  example: '2027',
                }),
              memo: z
                .string()
                .exactOptional()
                .openapi({
                  description: 'Friendly name to identify the card.',
                  example: 'New Card',
                }),
              pin: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Encrypted PIN block (in base64). Applies to cards of type `PHYSICAL` and `VIRTUAL`. See [Encrypted PIN Block](https://docs.lithic.com/docs/cards#encrypted-pin-block).',
                }),
              product_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Only applicable to cards of type `PHYSICAL`. This must be configured with Lithic before use. Specifies the configuration (i.e., physical card art) that the card should be manufactured with.',
                  example: '1',
                }),
              replacement_for: z
                .uuid()
                .exactOptional()
                .openapi({
                  description:
                    'Globally unique identifier for the card that this card will replace. If the card type is `PHYSICAL` it will be replaced by a `PHYSICAL` card. If the card type is `VIRTUAL` it will be replaced by a `VIRTUAL` card.',
                  example: '5e9483eb-8103-4e16-9794-2106111b2eca',
                }),
              replacement_substatus: z
                .enum([
                  'LOST',
                  'COMPROMISED',
                  'DAMAGED',
                  'END_USER_REQUEST',
                  'ISSUER_REQUEST',
                  'NOT_ACTIVE',
                  'SUSPICIOUS_ACTIVITY',
                  'INTERNAL_REVIEW',
                  'EXPIRED',
                  'UNDELIVERABLE',
                  'OTHER',
                ])
                .exactOptional()
                .openapi({
                  description:
                    "Card state substatus values for the card that this card will replace:\n* `LOST` - The physical card is no longer in the cardholder's possession due to being lost or never received by the cardholder.\n* `COMPROMISED` - Card information has been exposed, potentially leading to unauthorized access. This may involve physical card theft, cloning, or online data breaches.\n* `DAMAGED` - The physical card is not functioning properly, such as having chip failures or a demagnetized magnetic stripe.\n* `END_USER_REQUEST` - The cardholder requested the closure of the card for reasons unrelated to fraud or damage, such as switching to a different product or closing the account.\n* `ISSUER_REQUEST` - The issuer closed the card for reasons unrelated to fraud or damage, such as account inactivity, product or policy changes, or technology upgrades.\n* `NOT_ACTIVE` - The card hasn’t had any transaction activity for a specified period, applicable to statuses like `PAUSED` or `CLOSED`.\n* `SUSPICIOUS_ACTIVITY` - The card has one or more suspicious transactions or activities that require review. This can involve prompting the cardholder to confirm legitimate use or report confirmed fraud.\n* `INTERNAL_REVIEW` - The card is temporarily paused pending further internal review.\n* `EXPIRED` - The card has expired and has been closed without being reissued.\n* `UNDELIVERABLE` - The card cannot be delivered to the cardholder and has been returned.\n* `OTHER` - The reason for the status does not fall into any of the above categories. A comment should be provided to specify the reason.\n",
                }),
              replacement_comment: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Additional context or information related to the card that this card will replace.',
                }),
              replacement_account_token: z
                .uuid()
                .exactOptional()
                .openapi({
                  description:
                    "Restricted field limited to select use cases. Lithic will reach out directly if this field should be used. Globally unique identifier for the replacement card's account. If this field is specified, `replacement_for` must also be specified. If `replacement_for` is specified and this field is omitted, the replacement card's account will be inferred from the card being replaced.",
                  example: '5e9483eb-8103-4e16-9794-2106111b2eca',
                }),
              shipping_address: ShippingAddressSchema.exactOptional(),
              shipping_method: z
                .enum([
                  '2_DAY',
                  'BULK',
                  'EXPEDITED',
                  'EXPRESS',
                  'PRIORITY',
                  'STANDARD',
                  'STANDARD_WITH_TRACKING',
                ])
                .exactOptional()
                .openapi({
                  description:
                    'Shipping method for the card. Only applies to cards of type PHYSICAL.\nUse of options besides `STANDARD` require additional permissions.\n\n* `STANDARD` - USPS regular mail or similar international option, with no tracking\n* `STANDARD_WITH_TRACKING` - USPS regular mail or similar international option, with tracking\n* `PRIORITY` - USPS Priority, 1-3 day shipping, with tracking\n* `EXPRESS` - FedEx or UPS depending on card manufacturer, Express, 3-day shipping, with tracking\n* `2_DAY` - FedEx or UPS depending on card manufacturer, 2-day shipping, with tracking\n* `EXPEDITED` - FedEx or UPS depending on card manufacturer, Standard Overnight or similar international option, with tracking\n* `BULK` - Card will be shipped as part of a bulk fulfillment order. The shipping method and timeline are inherited from the parent bulk order.\n',
                }),
              spend_limit: z
                .int()
                .min(0)
                .exactOptional()
                .openapi({
                  description:
                    'Amount (in cents) to limit approved authorizations (e.g. 100000 would be a $1,000 limit). Transaction requests above the spend limit will be declined. Note that a spend limit of 0 is effectively no limit, and should only be used to reset or remove a prior limit. Only a limit of 1 or above will result in declined transactions due to checks against the card limit.',
                  example: 0,
                }),
              spend_limit_duration: SpendLimitDurationSchema.exactOptional(),
              state: z
                .enum(['OPEN', 'PAUSED'])
                .exactOptional()
                .openapi({
                  description:
                    'Card state values:\n* `OPEN` - Card will approve authorizations (if they match card and account parameters).\n* `PAUSED` - Card will decline authorizations, but can be resumed at a later time.\n',
                }),
              tags: TagsSchema.exactOptional().openapi({
                description:
                  'Key-value pairs to tag the card with. A replacement card does not inherit tags from the card it replaces. A card can have at most 50 tags, with keys up to 40 characters and values up to 500 characters\n',
              }),
              type: z
                .enum([
                  'MERCHANT_LOCKED',
                  'PHYSICAL',
                  'SINGLE_USE',
                  'VIRTUAL',
                  'UNLOCKED',
                  'DIGITAL_WALLET',
                ])
                .default('VIRTUAL')
                .openapi({
                  description:
                    'Card types:\n* `VIRTUAL` - Card will authorize at any merchant and can be added to a digital wallet like Apple Pay or Google Pay (if the card program is digital wallet-enabled).\n* `PHYSICAL` - Manufactured and sent to the cardholder. We offer white label branding, credit, ATM, PIN debit, chip/EMV, NFC and magstripe functionality. Reach out at [lithic.com/contact](https://lithic.com/contact) for more information.\n* `SINGLE_USE` - Card is closed upon first successful authorization.\n* `MERCHANT_LOCKED` - Card is locked to the first merchant that successfully authorizes the card.\n* `UNLOCKED` - *[Deprecated]* Similar behavior to VIRTUAL cards, please use VIRTUAL instead.\n* `DIGITAL_WALLET` - *[Deprecated]* Similar behavior to VIRTUAL cards, please use VIRTUAL instead.\n',
                }),
            })
            .openapi({ required: ['type'] }),
          examples: {
            createCard: {
              summary: 'Create card',
              value: {
                memo: 'New Card',
                spend_limit: 1000,
                spend_limit_duration: 'TRANSACTION',
                state: 'OPEN',
                tags: { 'risk-level': 'high' },
                type: 'VIRTUAL',
              },
            },
            createPhysicalCard: {
              summary: 'Create a physical card',
              value: {
                carrier: { qr_code_url: 'https://lithic.com/activate-card/1' },
                memo: 'New physical card',
                product_id: '783991122',
                shipping_address: {
                  address1: '123',
                  city: 'NEW YORK',
                  country: 'USA',
                  first_name: 'Johnny',
                  last_name: 'Appleseed',
                  postal_code: '10001',
                  state: 'NY',
                },
                state: 'OPEN',
                type: 'PHYSICAL',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: PciCardResponseSchema,
          example: {
            account_token: 'f3f4918c-dee9-464d-a819-4aa42901d624',
            card_program_token: '5e9483eb-8103-4e16-9794-2106111b2eca',
            cardholder_currency: 'USD',
            created: '2021-06-28T22:53:15Z',
            cvv: '776',
            exp_month: '06',
            exp_year: '2027',
            funding: {
              account_name: 'Sandbox',
              created: '2020-07-08T17:57:36Z',
              last_four: '5263',
              nickname: 'checking account',
              state: 'ENABLED',
              token: 'b0f0d91a-3697-46d8-85f3-20f0a585cbea',
              type: 'DEPOSITORY_CHECKING',
            },
            hostname: '',
            last_four: '4142',
            memo: 'New Card',
            pan: '4111111289144142',
            replacement_for: null,
            spend_limit: 1000,
            spend_limit_duration: 'TRANSACTION',
            state: 'OPEN',
            tags: { 'risk-level': 'high' },
            token: '7ef7d65c-9023-4da3-b113-3b8583fd7951',
            type: 'VIRTUAL',
            pin_status: 'NOT_SET',
          },
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    422: UnprocessableEntityResponse,
    429: TooManyRequestsResponse,
  },
})

