export const postV1CardsCardTokenProvisionRoute = createRoute({
  method: 'post',
  path: '/v1/cards/{card_token}/provision',
  tags: ['Card'],
  summary: 'Provision card (Digital Wallet)',
  description:
    "Allow your cardholders to directly add payment cards to the device's digital wallet (e.g. Apple Pay) with one touch from your app.\n\nThis requires some additional setup and configuration. Please [Contact Us](https://lithic.com/contact) or your Customer Success representative for more information.\n",
  operationId: 'postCardProvision',
  request: {
    params: z.object({ card_token: CardTokenDigitalWalletParamsSchema }),
    body: {
      description: 'Update request.',
      content: {
        'application/json': {
          schema: z
            .object({
              certificate: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "Only applicable if `digital_wallet` is `APPLE_PAY`. Omit to receive only `activationData` in the response. Apple's public leaf certificate. Base64 encoded in PEM format with headers `(-----BEGIN CERTIFICATE-----)` and trailers omitted. Provided by the device's wallet.",
                }),
              client_wallet_account_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Only applicable if `digital_wallet` is `GOOGLE_PAY` or `SAMSUNG_PAY`. Consumer ID that identifies the wallet account holder entity. Required for both wallets regardless of network, though the value is only used for cards on the Visa network and is ignored on Amex and Mastercard.',
                }),
              client_device_id: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Only applicable if `digital_wallet` is `GOOGLE_PAY` or `SAMSUNG_PAY`. Stable device identification set by the wallet provider. Required for both wallets regardless of network, though the value is only used for cards on the Visa network and is ignored on Amex and Mastercard.',
                }),
              digital_wallet: z
                .enum(['APPLE_PAY', 'GOOGLE_PAY', 'SAMSUNG_PAY'])
                .exactOptional()
                .openapi({ description: 'Name of digital wallet provider.' }),
              nonce: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "Only applicable if `digital_wallet` is `APPLE_PAY`. Omit to receive only `activationData` in the response. Base64 cryptographic nonce provided by the device's wallet.",
                }),
              nonce_signature: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "Only applicable if `digital_wallet` is `APPLE_PAY`. Omit to receive only `activationData` in the response. Base64 cryptographic nonce provided by the device's wallet.",
                }),
            })
            .openapi({ required: [] }),
          examples: {
            provisionGoogleCard: {
              summary: 'Provision a card in Google Pay',
              value: {
                digital_wallet: 'GOOGLE_PAY',
                client_device_id: 'd3538acf-e5df-4446-8ce6-588fa4472ac1',
                client_wallet_account_id: 'd3538acf-e5df-4446-8ce6-588fa4472ac1',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        "Returns `provisioning_payload`, a cryptographic payload representing a payment card that can be passed to a device's digital wallet. Each digital wallet has a different API; consult the wallet's documentation for more info.\n",
      content: {
        'application/json': {
          schema: z
            .object({
              provisioning_payload: z
                .xor([
                  z
                    .string()
                    .openapi({
                      description:
                        "Base64 encoded JSON payload representing a payment card that can be passed to a device's digital wallet. Applies to Google and Samsung Pay wallets.",
                    }),
                  z
                    .object({
                      activationData: z.string().exactOptional(),
                      ephemeralPublicKey: z.string().exactOptional(),
                      encryptedData: z.string().exactOptional(),
                    })
                    .openapi({
                      description:
                        'Object containing the fields required to add a card to Apple Pay. Applies only to Apple Pay wallet.',
                      required: [],
                    }),
                ])
                .exactOptional(),
            })
            .openapi({ required: [] }),
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    422: UnprocessableEntityResponse,
    429: TooManyRequestsResponse,
  },
})

