export const postV1CardAuthorizationsEventTokenChallengeResponseRoute = createRoute({
  method: 'post',
  path: '/v1/card_authorizations/{event_token}/challenge_response',
  tags: ['Card Authorizations'],
  summary: 'Respond to Authorization Challenge',
  description:
    "Card program's response to Authorization Challenge.\nPrograms that have Authorization Challenges configured as Out of Band receive a [card_authorization.challenge](https://docs.lithic.com/reference/cardauthorizationchallengewebhook) webhook when an authorization attempt triggers a challenge.\nThe card program should respond using this endpoint after the cardholder completes the challenge.",
  operationId: 'respondToAuthorizationChallenge',
  request: {
    params: z.object({
      event_token: z
        .uuid()
        .openapi({
          param: {
            name: 'event_token',
            in: 'path',
            required: true,
            description:
              'Globally unique identifier for the authorization event that triggered the challenge',
            schema: { type: 'string', format: 'uuid' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              response: z
                .enum(['APPROVE', 'DECLINE'])
                .openapi({
                  description:
                    'Whether the cardholder has approved or declined the issued challenge',
                }),
            })
            .openapi({
              title: 'Authorization Challenge Response',
              description: "Card program's response to Authorization Challenge",
              required: ['response'],
            }),
        },
      },
    },
  },
  responses: {
    200: { description: 'Challenge response recorded' },
    400: { description: 'Invalid request (e.g. challenge method does not support this endpoint)' },
    404: { description: 'Challenge not found' },
    409: { description: 'Challenge has already been completed' },
    410: { description: 'Challenge has expired' },
    500: { description: 'Lithic Error' },
  },
  security: [{ ApiKeyAuth: [] }],
})

