export const getV1DisputesRoute = createRoute({
  method: 'get',
  path: '/v1/disputes',
  tags: ['Chargeback'],
  summary: 'List chargeback requests',
  description: 'List chargeback requests.',
  operationId: 'getDisputes',
  request: {
    query: z.object({
      status: z
        .enum([
          'ARBITRATION',
          'CASE_CLOSED',
          'CASE_WON',
          'NEW',
          'PENDING_CUSTOMER',
          'PREARBITRATION',
          'REPRESENTMENT',
          'SUBMITTED',
        ])
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by status.',
            in: 'query',
            name: 'status',
            required: false,
            schema: {
              enum: [
                'ARBITRATION',
                'CASE_CLOSED',
                'CASE_WON',
                'NEW',
                'PENDING_CUSTOMER',
                'PREARBITRATION',
                'REPRESENTMENT',
                'SUBMITTED',
              ],
              type: 'string',
            },
          },
        }),
      transaction_tokens: z
        .preprocess(
          (val) =>
            val === undefined
              ? val
              : (Array.isArray(val) ? val : [val]).flatMap((item) =>
                  typeof item === 'string' ? item.split(',') : [item],
                ),
          z.array(z.uuid()).max(50),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'Transaction tokens to filter by.',
            explode: false,
            in: 'query',
            name: 'transaction_tokens',
            required: false,
            schema: { items: { format: 'uuid', type: 'string' }, maxItems: 50, type: 'array' },
            style: 'form',
          },
        }),
      begin: BeginTimeParamsSchema,
      end: EndTimeParamsSchema,
      ending_before: EndingBeforeParamsSchema,
      page_size: PageSizeParamsSchema,
      starting_after: StartingAfterParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(DisputeV1Schema),
              has_more: z.boolean().openapi({ description: 'More data exists.' }),
            })
            .openapi({ required: ['data', 'has_more'] }),
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    422: UnprocessableEntityResponse,
    429: TooManyRequestsResponse,
  },
})

