export const getV1EmbedCardRoute = createRoute({
  method: 'get',
  path: '/v1/embed/card',
  tags: ['Card'],
  summary: 'Embedded card UI',
  description:
    '**Deprecated.** Use the modern embedded card flow instead: create a session with `POST /v1/cards/{card_token}/embed` and render it via `GET /v1/embed`.\n\nHandling full card PANs and CVV codes requires that you comply with the Payment Card Industry Data Security Standards (PCI DSS). Some clients choose to reduce their compliance obligations by leveraging our embedded card UI solution documented below.\n\nIn this setup, PANs and CVV codes are presented to the end-user via a card UI that we provide, optionally styled in the customer\'s branding using a specified css stylesheet. A user\'s browser makes the request directly to api.lithic.com, so card PANs and CVVs never touch the API customer\'s servers while full card data is displayed to their end-users. The response contains an HTML document (see Embedded Card UI or Changelog for upcoming changes in January). This means that the url for the request can be inserted straight into the `src` attribute of an iframe.\n\n```html\n<iframe id="card-iframe"\n        src="https://sandbox.lithic.com/v1/embed/card?embed_request=eyJjc3MiO...;hmac=r8tx1..."\n        allow="clipboard-write" class="content"></iframe>\n```\n\nYou should compute the request payload on the server side. You can render it (or the whole iframe) on the server or make an ajax call from your front end code, but **do not ever embed your API key into front end code, as doing so introduces a serious security vulnerability**.\n',
  operationId: 'getEmbedCard',
  request: {
    query: z.object({
      embed_request: z
        .string()
        .openapi({
          param: {
            description:
              'A base64 encoded JSON string of an EmbedRequest to specify which card to load.',
            in: 'query',
            name: 'embed_request',
            required: true,
            schema: { type: 'string' },
          },
        }),
      hmac: z
        .string()
        .openapi({
          param: {
            description: 'SHA256 HMAC of the embed_request JSON string with base64 digest.',
            in: 'query',
            name: 'hmac',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        "The endpoint returns an HTML document similar to the one below. It is up to the API client to provide css styles for these elements in the EmbedRequest. You can always rely on the `card`, `pan`, `expiry`, `cvv`, and `alert` ids, as well as the `pan-separator` class. You shouldn't make any other assumptions about the structure of the document as it could change at any time.\n\nNote that using the default style sheet there is no visual indication that copying is happening on-click, and you may need to add on-click styling yourself.\n",
      content: {
        'text/html': {
          schema: z.string(),
          examples: {
            html: {
              summary: 'Card UI',
              value:
                '<html>\n<head>\n<link rel="stylesheet" type="text/css" href="https://demo.lithic.com/backend/embedded.css">\n<style>\n    #alert { display: none; }\n</style>\n<script type="text/javascript">\n    var timeout;\n\n    function clearAlertDelay() {\n        clearTimeout(timeout);\n        var messageDiv = document.getElementById(\'alert\');\n        timeout = window.setTimeout(\n            function() {\n                messageDiv.className = "empty";\n                messageDiv.innerText = "";\n            },\n            1200\n        );\n    }\n\n    function copySuccess(divId) {\n        var messageDiv = document.getElementById(\'alert\');\n        messageDiv.innerText = divId + " copied to clipboard";\n        messageDiv.className = "success";\n        console.log(\'Copying to clipboard was successful!\');\n        clearAlertDelay();\n    }\n\n    function copyFailed(divId) {\n        var messageDiv = document.getElementById(\'alert\');\n        messageDiv.innerText = "error copying " + divId;\n        messageDiv.className = "error";\n        console.error(\'Copying to clipboard failed\');\n        clearAlertDelay();\n    }\n\n    function copyToClip(divId) {\n        var messageDiv = document.getElementById(\'alert\');\n        var copyEl = document.getElementById(divId);\n        var copyText = copyEl.textContent;\n        navigator.clipboard.writeText(copyText)\n            .then(function () {\n                copySuccess(divId);\n                clearAlertDelay();\n            })\n            .catch(function(err) {\n                try {\n                    var copied = false;\n                    if (document.createRange) {\n                        range = document.createRange();\n                        range.selectNode(copyEl)\n                        select = window.getSelection();\n                        select.removeAllRanges();\n                        select.addRange(range);\n                        copied = document.execCommand(\'copy\');\n                        select.removeAllRanges();\n                    }\n                    else {\n                        range = document.body.createTextRange();\n                        range.moveToElementText(copyEl);\n                        range.select();\n                        copied = document.execCommand(\'copy\');\n                    }\n\n                    if (copied) {\n                        copySuccess(divId);\n                    }\n                    else {\n                        copyFailed(divId);\n                    }\n                }\n                catch (err) {\n                    copyFailed(divId);\n                }\n                clearAlertDelay();\n            })\n    }\n</script>\n</head>\n<body>\n    <div id="card">\n        <div id="pan" onclick="copyToClip(\'pan\')">9999<span class=\'pan-separator\'></span>9999<span class=\'pan-separator\'></span>9999<span class=\'pan-separator\'></span>9999</div>\n        <div id="expiry">\n            <span id="month" onclick="copyToClip(\'month\')">08</span>\n            <span id="separator">/</span>\n            <span id="year" onclick="copyToClip(\'year\')">27</span>\n        </div>\n        <div id="cvv" onclick="copyToClip(\'cvv\')">574</div>\n        <div id="alert" class="empty"></div>\n    </div>\n</body>\n</html>\n',
            },
          },
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    422: UnprocessableEntityResponse,
    429: TooManyRequestsResponse,
  },
  deprecated: true,
})

export const getV1EmbedRoute = createRoute({
  method: 'get',
  path: '/v1/embed',
  tags: ['Card'],
  summary: 'Get card embed iframe',
  description:
    'Returns a Lithic-hosted HTML document for a single card detail or PIN setting control. Use\nthe URL, including its query parameters, as the `src` of an iframe. The session must be created\non your server with `POST /v1/cards/{card_token}/embed`.\n',
  operationId: 'getCardEmbed',
  request: {
    query: z.object({
      session: z
        .string()
        .openapi({
          param: {
            description:
              'The short-lived credential returned by the session creation endpoint. Treat it as\nsensitive and use it only in the iframe `src`.\n',
            example: 'eyJhb...',
            in: 'query',
            name: 'session',
            required: true,
            schema: { type: 'string' },
          },
        }),
      type: z
        .enum(['PAN', 'CVV', 'EXP_MONTH', 'EXP_YEAR', 'PIN_SETTING'])
        .openapi({
          param: {
            description:
              'The type of embed to return.\n`CARD_EMBED` sessions support `PAN`, `CVV`, `EXP_MONTH`, and `EXP_YEAR`.\n`PIN_SETTING_EMBED` sessions support only `PIN_SETTING`.\n',
            example: 'PAN',
            in: 'query',
            name: 'type',
            required: true,
            schema: {
              enum: ['PAN', 'CVV', 'EXP_MONTH', 'EXP_YEAR', 'PIN_SETTING'],
              type: 'string',
            },
          },
        }),
      styles: z
        .string()
        .max(4096)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Optional base64-encoded JSON object containing base CSS declarations and nested\npseudo-class declarations to apply to the iframe. URL-encode the base64 value when\nadding it to the query string. Styles that load external resources are not permitted.\nThe encoded value cannot exceed 4096 characters.\n\nSupported pseudo-classes are `:first-child`, `:last-child`, `:enabled`, `:read-write`,\n`:read-only`, `:placeholder-shown`, `:valid`, `:invalid`, `:disabled`, `:hover`,\n`:focus-within`, `:focus`, `:focus-visible`, and `:active`.\n',
            example: 'eyJjb2xvciI6ImJsYWNrIiwiOmhvdmVyIjp7ImNvbG9yIjoiYmx1ZSJ9fQ==',
            in: 'query',
            name: 'styles',
            required: false,
            schema: { format: 'byte', maxLength: 4096, type: 'string' },
          },
        }),
      configuration: z
        .string()
        .max(4096)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Optional standard base64-encoded JSON configuration for the requested iframe. URL-encode\nthe base64 value when adding it to the query string. The encoded value cannot exceed 4096\ncharacters; malformed or oversized values are rejected with a `400` response.\n\n`PIN_SETTING` supports a `pin_setting` object with an optional `placeholder` string and an\noptional `layout`. `placeholder` defaults to an empty string and applies only to the\nsingle-input layout. `layout` accepts `SINGLE_INPUT` or `MULTI_INPUT` and defaults to\n`SINGLE_INPUT`. The multi-input layout renders one single-digit input for each digit allowed\nby the embed session\'s `max_pin_length`.\n\nDecoded example: `{"pin_setting":{"layout":"MULTI_INPUT"}}`\n',
            example: 'eyJwaW5fc2V0dGluZyI6eyJsYXlvdXQiOiJNVUxUSV9JTlBVVCJ9fQ==',
            in: 'query',
            name: 'configuration',
            required: false,
            schema: { format: 'byte', maxLength: 4096, type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Lithic-hosted card embed HTML.',
      content: {
        'text/html': {
          schema: z.string(),
          examples: {
            html: {
              summary: 'Card embed iframe',
              value: '<!doctype html><html><body><div id="app"></div></body></html>',
            },
          },
        },
      },
    },
    400: BadRequestResponse,
    401: {
      description:
        'The embed session is missing, invalid, expired, or not authorized for the requested type.',
      content: { 'application/json': { schema: ErrorSchema } },
    },
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
  },
  security: [],
})

