export const postV1SimulateAuthorizeRoute = createRoute({
  method: 'post',
  path: '/v1/simulate/authorize',
  tags: ['Transaction'],
  summary: 'Simulate authorization',
  description:
    'Simulates an authorization request from the card network as if it came from a merchant acquirer.\nIf you are configured for ASA, simulating authorizations requires your ASA client to be set up properly, i.e. be able to respond to the ASA request with a valid JSON. For users that are not configured for ASA, a daily transaction limit of $5000 USD is applied by default. You can update this limit via the [update account](https://docs.lithic.com/reference/patchaccountbytoken) endpoint.\n',
  operationId: 'postSimulateAuthorize',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              amount: z
                .int()
                .min(0)
                .max(2000000000)
                .openapi({
                  description:
                    'Amount (in cents) to authorize. For credit authorizations and financial credit authorizations, any value entered will be converted into a negative amount in the simulated transaction. For example, entering 100 in this field will result in a -100 amount in the transaction. For balance inquiries, this field must be set to 0.',
                }),
              billing_currency: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    '3-character alphabetic ISO 4217 currency code for the cardholder billing amount. Permitted values are USD, GBP, EUR and CAD, and any other ISO 4217 code returns a 422. Defaults to USD',
                  example: 'CAD',
                }),
              descriptor: z
                .string()
                .min(1)
                .max(25)
                .openapi({ description: 'Merchant descriptor.', example: 'COFFEE SHOP' }),
              mcc: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'Merchant category code for the transaction to be simulated. A four-digit number listed in ISO 18245.\nSupported merchant category codes can be found [here](https://docs.lithic.com/docs/transactions#merchant-category-codes-mccs).\n',
                  example: '5812',
                }),
              merchant_acceptor_id: z
                .string()
                .min(1)
                .max(15)
                .exactOptional()
                .openapi({
                  description: 'Unique identifier to identify the payment card acceptor.',
                  example: 'OODKZAPJVN4YS7O',
                }),
              merchant_acceptor_city: z
                .string()
                .max(13)
                .exactOptional()
                .openapi({ description: 'Merchant acceptor city', example: 'LOS ANGELES' }),
              merchant_acceptor_state: z
                .string()
                .max(3)
                .exactOptional()
                .openapi({
                  description: 'Merchant acceptor state/province (ISO 3166-2 subdivision code)',
                  example: 'CA',
                }),
              merchant_acceptor_country: z
                .string()
                .length(3)
                .exactOptional()
                .openapi({
                  description: 'Merchant acceptor country code (ISO 3166-1 alpha-3)',
                  example: 'USA',
                }),
              merchant_amount: z
                .int()
                .exactOptional()
                .openapi({
                  description:
                    'Amount of the transaction to be simulated in currency specified in merchant_currency, including any acquirer fees.',
                }),
              merchant_currency: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    '3-character alphabetic ISO 4217 currency code for the merchant amount. Only used when merchant_amount is set, and defaults to GBP in that case. Without merchant_amount, the merchant amount uses the billing currency. Permitted values are USD, GBP, EUR and CAD, and any other ISO 4217 code returns a 422',
                  example: 'GBP',
                }),
              pan: z
                .string()
                .length(16)
                .openapi({
                  description: 'Sixteen digit card number.',
                  example: '4111111289144142',
                }),
              partial_approval_capable: z
                .boolean()
                .exactOptional()
                .openapi({
                  description:
                    'Set to true if the terminal is capable of partial approval otherwise false.\nPartial approval is when part of a transaction is approved and another\npayment must be used for the remainder.\n',
                }),
              pin: z
                .string()
                .min(4)
                .max(12)
                .exactOptional()
                .openapi({
                  description:
                    'Simulate entering a PIN. If omitted, PIN check will not be performed.',
                  example: '1234',
                }),
              settlement_currency: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    '3-character alphabetic ISO 4217 currency code for the settlement amount. Permitted values are USD, GBP, EUR and CAD, and any other ISO 4217 code returns a 422. Defaults to the value of billing_currency. Only single message (financial) authorizations carry a settlement amount, and the value is ignored for dual message authorizations',
                  example: 'CAD',
                }),
              status: z
                .enum([
                  'AUTHORIZATION',
                  'BALANCE_INQUIRY',
                  'CREDIT_AUTHORIZATION',
                  'FINANCIAL_AUTHORIZATION',
                  'FINANCIAL_CREDIT_AUTHORIZATION',
                ])
                .default('AUTHORIZATION')
                .exactOptional()
                .openapi({
                  description:
                    "Type of event to simulate.\n* `AUTHORIZATION` is a dual message purchase authorization, meaning a subsequent clearing step is required to settle the transaction.\n* `BALANCE_INQUIRY` is a $0 authorization requesting the balance held on the card, and is most often observed when a cardholder requests to view a card's balance at an ATM.\n* `CREDIT_AUTHORIZATION` is a dual message request from a merchant to authorize a refund, meaning a subsequent clearing step is required to settle the transaction.\n* `FINANCIAL_AUTHORIZATION` is a single message request from a merchant to debit funds immediately (such as an ATM withdrawal), and no subsequent clearing is required to settle the transaction.\n* `FINANCIAL_CREDIT_AUTHORIZATION` is a single message request from a merchant to credit funds immediately, and no subsequent clearing is required to settle the transaction.\n",
                  example: 'AUTHORIZATION',
                }),
            })
            .openapi({ required: ['amount', 'descriptor', 'pan'] }),
          examples: {
            simulateAuthorization: {
              summary: 'Simulate an authorization',
              value: {
                amount: 3831,
                descriptor: 'COFFEE SHOP',
                merchant_acceptor_city: 'LOS ANGELES',
                merchant_acceptor_state: 'CA',
                merchant_acceptor_country: 'USA',
                pan: '4111111289144142',
              },
            },
            simulateBalanceInquiry: {
              summary: 'Simulate a balance inquiry',
              value: {
                amount: 0,
                descriptor: 'NEIGHBORHOOD ATM',
                pan: '4111111289144142',
                status: 'BALANCE_INQUIRY',
              },
            },
            simulateFinancialCreditAuthorization: {
              summary: 'Simulate a financial credit authorization',
              value: {
                amount: 3831,
                descriptor: 'COFFEE SHOP',
                pan: '4111111289144142',
                status: 'FINANCIAL_CREDIT_AUTHORIZATION',
              },
            },
            simulateCadAuthorization: {
              summary: 'Simulate a CAD authorization',
              value: {
                amount: 3831,
                billing_currency: 'CAD',
                descriptor: 'COFFEE SHOP',
                pan: '4111111289144142',
                status: 'FINANCIAL_AUTHORIZATION',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              debugging_request_id: z
                .uuid()
                .exactOptional()
                .openapi({
                  description: 'Debugging request ID to share with Lithic Support team.',
                }),
              token: z
                .uuid()
                .exactOptional()
                .openapi({
                  description:
                    'A unique token to reference this transaction with later calls to void or clear the authorization.',
                }),
            })
            .openapi({ required: [] }),
          example: {
            debugging_request_id: 'd31645af-da9e-4952-b7dc-3ffb06618b39',
            token: 'fabd829d-7f7b-4432-a8f2-07ea4889aaac',
          },
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    422: SimulateAuthorizationFailureResponse,
    429: TooManyRequestsResponse,
  },
})

export const postV1SimulateClearingRoute = createRoute({
  method: 'post',
  path: '/v1/simulate/clearing',
  tags: ['Transaction'],
  summary: 'Simulate clearing',
  description:
    'Clears an existing authorization, either debit or credit. After this event, the transaction transitions from `PENDING` to `SETTLED` status.\n\nIf `amount` is not set, the full amount of the transaction will be cleared. This endpoint may be called multiple times against the same authorization to simulate a multiple-completion scenario, with each call creating a separate clearing event.\n',
  operationId: 'postSimulateClearing',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              amount: z
                .int()
                .max(2000000000)
                .exactOptional()
                .openapi({
                  description:
                    "Amount (in cents) to clear. Typically this will match the amount in the original authorization, but can be higher or lower. The sign of this amount will automatically match the sign of the original authorization's amount. For example, entering 100 in this field will result in a -100 amount in the transaction, if the original authorization is a credit authorization.\n\nIf `amount` is not set, the full amount of the transaction will be cleared. This endpoint may be called multiple times against the same authorization to simulate a multiple-completion scenario, with each call creating a separate clearing event.\n",
                }),
              token: z
                .uuid()
                .openapi({
                  description:
                    'The transaction token returned from the /v1/simulate/authorize response.',
                }),
            })
            .openapi({ required: ['token'] }),
          examples: {
            simulateClear: {
              summary: 'Simulate clearing a transaction',
              value: { amount: 0, token: 'fabd829d-7f7b-4432-a8f2-07ea4889aaac' },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              debugging_request_id: z
                .uuid()
                .exactOptional()
                .openapi({
                  description: 'Debugging request ID to share with Lithic Support team.',
                }),
            })
            .openapi({ required: [] }),
          example: { debugging_request_id: '3ec51ef1-b68d-4243-be6c-2204229b09cf' },
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    422: UnprocessableEntityResponse,
    429: TooManyRequestsResponse,
  },
})

