export const postV1SimulateVoidRoute = createRoute({
  method: 'post',
  path: '/v1/simulate/void',
  tags: ['Transaction'],
  summary: 'Simulate void',
  description:
    'Voids a pending authorization. If `amount` is not set, the full amount will be voided. Can be used on partially voided transactions but not partially cleared transactions. _Simulating an authorization expiry on credit authorizations or credit authorization advice is not currently supported but will be added soon._\n',
  operationId: 'postSimulateVoid',
  request: {
    body: {
      content: {
        'application/json': {
          schema: z
            .object({
              amount: z
                .int()
                .min(0)
                .max(2000000000)
                .exactOptional()
                .openapi({
                  description:
                    'Amount (in cents) to void. Typically this will match the amount in the original authorization, but can be less. Applies to authorization reversals only. An authorization expiry will always apply to the full pending amount.',
                }),
              token: z
                .uuid()
                .openapi({
                  description:
                    'The transaction token returned from the /v1/simulate/authorize response.',
                }),
              type: z
                .enum(['AUTHORIZATION_EXPIRY', 'AUTHORIZATION_REVERSAL'])
                .default('AUTHORIZATION_REVERSAL')
                .exactOptional()
                .openapi({
                  description:
                    'Type of event to simulate. Defaults to `AUTHORIZATION_REVERSAL`.\n\n* `AUTHORIZATION_EXPIRY` indicates authorization has expired and been reversed by Lithic.\n* `AUTHORIZATION_REVERSAL` indicates authorization was reversed by the merchant.\n',
                  example: 'AUTHORIZATION_EXPIRY',
                }),
            })
            .openapi({ required: ['token'] }),
          examples: {
            simulateAuthorizationExpiry: {
              summary: 'Simulate expiring a transaction',
              value: {
                amount: 100,
                token: 'fabd829d-7f7b-4432-a8f2-07ea4889aaac',
                type: 'AUTHORIZATION_EXPIRY',
              },
            },
            simulateAuthorizationReversal: {
              summary: 'Simulate reversing a transaction',
              value: {
                amount: 100,
                token: 'fabd829d-7f7b-4432-a8f2-07ea4889aaac',
                type: 'AUTHORIZATION_REVERSAL',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              debugging_request_id: z
                .uuid()
                .exactOptional()
                .openapi({
                  description: 'Debugging request ID to share with Lithic Support team.',
                }),
            })
            .openapi({ required: [] }),
          example: { debugging_request_id: '3ec51ef1-b68d-4243-be6c-2204229b09cf' },
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    404: NotFoundResponse,
    429: TooManyRequestsResponse,
  },
})

