export const getV1TransactionMonitoringCasesRoute = createRoute({
  method: 'get',
  path: '/v1/transaction_monitoring/cases',
  tags: ['Transaction Monitoring'],
  summary: 'List cases',
  description: 'Lists transaction monitoring cases, optionally filtered.',
  operationId: 'listTransactionMonitoringCases',
  request: {
    query: z.object({
      queue_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            name: 'queue_token',
            in: 'query',
            required: false,
            description: 'Only return cases belonging to the provided queue.',
            schema: { type: 'string', format: 'uuid' },
          },
        }),
      status: CaseStatusSchema.openapi({
        param: {
          name: 'status',
          in: 'query',
          required: false,
          description: 'Only return cases with the provided status.',
          schema: { $ref: '#/components/schemas/case-status' },
        },
      }).exactOptional(),
      assignee: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            name: 'assignee',
            in: 'query',
            required: false,
            description:
              'Only return cases assigned to the provided value. Pass an empty string to return only unassigned cases.',
            schema: { type: 'string' },
          },
        }),
      rule_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            name: 'rule_token',
            in: 'query',
            required: false,
            description: 'Only return cases triggered by the provided transaction monitoring rule.',
            schema: { type: 'string', format: 'uuid' },
          },
        }),
      transaction_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            name: 'transaction_token',
            in: 'query',
            required: false,
            description: 'Only return cases that include the provided transaction.',
            schema: { type: 'string', format: 'uuid' },
          },
        }),
      card_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            name: 'card_token',
            in: 'query',
            required: false,
            description: 'Only return cases that include transactions on the provided card.',
            schema: { type: 'string', format: 'uuid' },
          },
        }),
      account_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            name: 'account_token',
            in: 'query',
            required: false,
            description: 'Only return cases that include transactions on the provided account.',
            schema: { type: 'string', format: 'uuid' },
          },
        }),
      entity_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            name: 'entity_token',
            in: 'query',
            required: false,
            description:
              'Only return cases associated with the provided entity. Accepts a card, account, or financial account token. Cases with a `PROGRAM` entity have no entity token and are never returned by this filter.',
            schema: { type: 'string', format: 'uuid' },
          },
        }),
      sort_by: CaseSortBySchema.openapi({
        param: {
          name: 'sort_by',
          in: 'query',
          required: false,
          description: 'Sort order for the returned cases.',
          schema: { $ref: '#/components/schemas/case-sort-by' },
        },
      }).exactOptional(),
      begin: BeginTimeParamsSchema,
      end: EndTimeParamsSchema,
      starting_after: StartingAfter2ParamsSchema,
      ending_before: EndingBefore2ParamsSchema,
      page_size: ParametersPageSizeParamsSchema,
    }),
  },
  responses: {
    200: {
      description: 'Cases',
      content: {
        'application/json': {
          schema: z
            .object({ data: z.array(MonitoringCaseSchema), has_more: z.boolean() })
            .openapi({ required: ['data', 'has_more'] }),
        },
      },
    },
    400: ResponsesBadRequestResponse,
  },
})

