export const getV1NetworkProgramsRoute = createRoute({
  method: 'get',
  path: '/v1/network_programs',
  tags: ['Network Program'],
  summary: 'List network programs',
  description: 'List network programs.',
  operationId: 'getNetworkPrograms',
  request: {
    query: z.object({
      page_size: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            description: 'Page size (for pagination).',
            in: 'query',
            name: 'page_size',
            schema: { default: 50, maximum: 100, minimum: 1, type: 'integer' },
            required: false,
          },
        }),
      begin: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description:
              'Date string in RFC 3339 format. Only entries created on or after the specified time will be included. UTC time zone.',
            in: 'query',
            name: 'begin',
            schema: { format: 'date-time', type: 'string' },
            required: false,
          },
        }),
      end: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description:
              'Date string in RFC 3339 format. Only entries created before the specified time will be included. UTC time zone.',
            in: 'query',
            name: 'end',
            schema: { format: 'date-time', type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'OK',
      content: {
        'application/json': {
          schema: z
            .object({
              data: z.array(NetworkProgramSchema),
              has_more: z
                .boolean()
                .openapi({
                  description: 'Whether there are more network programs to be retrieved.',
                }),
            })
            .openapi({ required: ['data', 'has_more'] }),
        },
      },
    },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    429: TooManyRequestsResponse,
  },
})

