export const getV2DisputesRoute = createRoute({
  method: 'get',
  path: '/v2/disputes',
  tags: ['Managed Disputes'],
  summary: 'List disputes',
  description: 'Returns a paginated list of disputes.',
  operationId: 'getDisputesV2',
  request: {
    query: z.object({
      begin: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'RFC 3339 timestamp for filtering by created date, inclusive.',
            in: 'query',
            name: 'begin',
            required: false,
            schema: { format: 'date-time', type: 'string' },
          },
        }),
      end: z.iso
        .datetime({ offset: true })
        .exactOptional()
        .openapi({
          param: {
            description: 'RFC 3339 timestamp for filtering by created date, inclusive.',
            in: 'query',
            name: 'end',
            required: false,
            schema: { format: 'date-time', type: 'string' },
          },
        }),
      page_size: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int().min(1).max(100),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            description: 'Number of items to return.',
            in: 'query',
            name: 'page_size',
            required: false,
            schema: { default: 50, maximum: 100, minimum: 1, type: 'integer' },
          },
        }),
      starting_after: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "A cursor representing an item's token after which a page of results should begin. Used to retrieve the next page of results after this item.",
            in: 'query',
            name: 'starting_after',
            required: false,
            schema: { type: 'string' },
          },
        }),
      ending_before: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              "A cursor representing an item's token before which a page of results should end. Used to retrieve the previous page of results before this item.",
            in: 'query',
            name: 'ending_before',
            required: false,
            schema: { type: 'string' },
          },
        }),
      disputed_transaction_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter by the token of the transaction being disputed. Corresponds with transaction_series.related_transaction_token in the Dispute.',
            in: 'query',
            name: 'disputed_transaction_token',
            required: false,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
      claim_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            description:
              "Filter by the token of the claim the dispute was filed under. Returns the disputes created from that claim's disputed transaction events.",
            in: 'query',
            name: 'claim_token',
            required: false,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
      card_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by card token.',
            in: 'query',
            name: 'card_token',
            required: false,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
      account_token: z
        .uuid()
        .exactOptional()
        .openapi({
          param: {
            description: 'Filter by account token.',
            in: 'query',
            name: 'account_token',
            required: false,
            schema: { format: 'uuid', type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: { description: 'OK', content: { 'application/json': { schema: DisputesResponseSchema } } },
    400: BadRequestResponse,
    401: UnauthorizedResponse,
    422: UnprocessableEntityResponse,
    429: TooManyRequestsResponse,
  },
})

